-- 4. Questions -------------------------------------------------------------
INSERT INTO public.quiz_questions (id, quiz_id, question, kind, options, correct_index, explanation, position)
SELECT v.id, v.quiz_id, v.question, v.kind, v.options, v.correct_index, v.explanation, v.position
  FROM (VALUES
    ('a0e2ede3-771a-5dfc-905d-a9881f236bc0'::uuid, '31cc53f7-6588-5461-b0aa-1874651afd81'::uuid, 'Que mesure la qualité physique appelée « force » ?', 'mcq', '["L’amplitude d’une articulation","La durée pendant laquelle on peut courir","La tension qu’on peut produire contre une résistance","La rapidité avec laquelle on réagit à un signal"]'::jsonb, 2, 'La force, c’est produire de la tension contre une résistance : soulever, pousser, lancer.', 1),
    ('b55a0eb2-7d31-5c2b-948a-af217da0746a'::uuid, '31cc53f7-6588-5461-b0aa-1874651afd81'::uuid, 'Quelles fibres musculaires fournissent surtout force et vitesse, mais se fatiguent vite ?', 'mcq', '["Les fibres rapides, de type II","Les fibres lentes, de type I","Les fibres du cœur uniquement","Aucune fibre : c’est le squelette"]'::jsonb, 0, 'Les fibres rapides produisent beaucoup de puissance mais s’épuisent vite ; les fibres lentes durent plus longtemps.', 2),
    ('6151d951-a666-5e93-81f6-7938f8f459a2'::uuid, '31cc53f7-6588-5461-b0aa-1874651afd81'::uuid, 'La proportion de fibres lentes et rapides décide de tout : on ne peut pas progresser contre elle.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle est en partie héritée, mais tout s’entraîne : chacun peut progresser dans la force, la vitesse et l’endurance.', 3),
    ('f2047cb4-d3bd-5d22-bd08-0182d79ff3d3'::uuid, '31cc53f7-6588-5461-b0aa-1874651afd81'::uuid, 'Quelle méthode convient le mieux pour devenir plus vite en sprint ?', 'mcq', '["Des sorties de deux heures à allure lente","Des sprints courts avec récupération complète","Des étirements de dix minutes","Un sprint chaque minute sans pause"]'::jsonb, 1, 'Pour rester vraiment vite, il faut repartir frais : sprints courts et récupération complète entre chaque.', 4),
    ('ba7815fd-faab-53da-b72b-71af64c35ecf'::uuid, '31cc53f7-6588-5461-b0aa-1874651afd81'::uuid, 'Quel moteur est entraîné par de longues sorties à allure modérée ?', 'mcq', '["La force maximale","Le temps de réaction","L’endurance","La souplesse"]'::jsonb, 2, 'L’endurance aérobie se construit en tenant longtemps : des efforts longs et réguliers.', 5),
    ('57fa01e7-991b-5bc1-8806-c2a4630fc916'::uuid, '31cc53f7-6588-5461-b0aa-1874651afd81'::uuid, 'Le test navette de Luc Léger, créé en 1982, évalue…', 'mcq', '["la détente verticale","la souplesse","l’endurance","la précision de tir"]'::jsonb, 2, 'On court en aller-retour sur 20 mètres au rythme de bips de plus en plus rapides : le test mesure l’endurance.', 6),
    ('5027b179-4456-5b76-80a7-da7d52bca5e5'::uuid, '31cc53f7-6588-5461-b0aa-1874651afd81'::uuid, 'À 14 ans, il vaut mieux soulever la charge maximale pour progresser plus vite en force.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La force maximale attend la fin de la croissance : à cet âge, on travaille la technique et le poids du corps.', 7),
    ('56bcb838-634d-56b5-b36d-b1b5bfb78b5b'::uuid, '31cc53f7-6588-5461-b0aa-1874651afd81'::uuid, 'Parmi ces trois composantes, laquelle ne fait PAS partie de la vitesse ?', 'mcq', '["La fréquence des mouvements","Le temps de réaction","L’amplitude de la foulée","La souplesse du tronc"]'::jsonb, 3, 'La vitesse regroupe réaction, fréquence et amplitude. La souplesse est une autre qualité.', 8),
    ('54897a4f-3045-59db-8bb1-3a61a3e88cf0'::uuid, '31cc53f7-6588-5461-b0aa-1874651afd81'::uuid, 'Que travaille le saut en longueur sans élan ?', 'mcq', '["La détente des jambes","L’endurance aérobie","La coordination des bras","La souplesse du dos"]'::jsonb, 0, 'Ce test mesure la puissance des jambes sur un seul effort, c’est-à-dire la détente.', 9),
    ('eb3cb03e-6739-5be6-b039-795e92ee1de7'::uuid, '31cc53f7-6588-5461-b0aa-1874651afd81'::uuid, 'La coordination est la capacité de faire travailler ensemble ses membres et son regard.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Dribbler en courant ou réceptionner un ballon demande à tout le corps de travailler ensemble : c’est la coordination.', 10),
    ('0f130035-ef38-5f7a-8125-380c3a9f0c21'::uuid, '31cc53f7-6588-5461-b0aa-1874651afd81'::uuid, 'Pourquoi refaire un test physique trois mois plus tard ?', 'mcq', '["Parce que les résultats changent chaque jour","Pour remplacer l’échauffement","Pour battre les autres élèves","Pour se comparer à soi-même et vérifier ses progrès"]'::jsonb, 3, 'Le but d’un test est de mesurer sa propre progression : même test, mêmes conditions, quelques mois d’écart.', 11),
    ('2dcc5040-2a6f-5919-ada1-f80aca5397f4'::uuid, '31cc53f7-6588-5461-b0aa-1874651afd81'::uuid, 'Quelles qualités un adolescent de 13 à 15 ans travaille-t-il particulièrement bien ?', 'mcq', '["La force maximale","Aucune : il est trop jeune","Uniquement la souplesse","La coordination et la vitesse"]'::jsonb, 3, 'Le cerveau apprend vite les gestes nouveaux à cet âge : coordination et vitesse progressent très bien.', 12),
    ('f26ed744-097e-5048-ac90-81f40048f6e3'::uuid, 'adfff92d-a463-5a31-8ff1-ab4ac5d19389'::uuid, 'Qu’est-ce que l’hypertrophie musculaire ?', 'mcq', '["L’épaississement des fibres qui composent le muscle","L’augmentation du nombre de muscles du corps","La fonte du muscle quand on arrête le sport","L’allongement des os pendant la croissance"]'::jsonb, 0, 'Un muscle grossit parce que chacune de ses fibres s’épaissit : leur nombre, lui, ne change presque pas.', 1),
    ('3f685310-ba3d-5e19-b942-a9acf39e3cc6'::uuid, 'adfff92d-a463-5a31-8ff1-ab4ac5d19389'::uuid, 'Après une séance, pendant combien de temps le muscle fabrique-t-il des protéines pour se réparer ?', 'mcq', '["Environ 24 à 48 heures","Une dizaine de minutes","Une semaine entière","Seulement pendant la séance"]'::jsonb, 0, 'C’est pendant ces 24 à 48 heures de récupération que la fibre se reconstruit un peu plus épaisse : d’où le repos entre deux séances du même muscle.', 2),
    ('b379ceb8-a1f7-5c10-a7b4-b49ce2c75c5c'::uuid, 'adfff92d-a463-5a31-8ff1-ab4ac5d19389'::uuid, 'Plus on a de courbatures, plus le muscle grossit.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La courbature signale des micro-lésions, pas le progrès : on progresse souvent sans courbature, et on peut avoir des courbatures sans progresser.', 3),
    ('3cee0690-b489-57a2-91b6-809524b32204'::uuid, 'adfff92d-a463-5a31-8ff1-ab4ac5d19389'::uuid, 'Quelle fourchette de répétitions par série vise le mieux la prise de muscle ?', 'mcq', '["8 à 12","1 à 3","30 à 50","Au moins 100"]'::jsonb, 0, 'Entre 8 et 12 répétitions avec une charge qui fatigue à la fin de la série : assez lourd pour tendre le muscle, assez long pour le fatiguer.', 4),
    ('95e24dd9-64a6-5e5e-a6bb-2415f16e837c'::uuid, 'adfff92d-a463-5a31-8ff1-ab4ac5d19389'::uuid, 'Quel est le levier principal de l’hypertrophie ?', 'mcq', '["La tension mécanique : la force produite contre une résistance","La température du muscle","La vitesse à laquelle on court","Le nombre de muscles sollicités"]'::jsonb, 0, 'Sans tension mécanique, rien ne pousse la fibre à s’épaissir ; la brûlure et les micro-lésions ne font que l’accompagner.', 5),
    ('0e804029-310b-50c8-af26-08542c99c61e'::uuid, 'adfff92d-a463-5a31-8ff1-ab4ac5d19389'::uuid, 'Entraîner le même muscle tous les jours le fait grossir plus vite.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Sans 48 heures de repos, le muscle n’a pas le temps de se reconstruire : on casse un mur qu’on n’a pas fini de remonter.', 6),
    ('0c65c835-5cd2-51c3-9374-4a4f2ae27c1c'::uuid, 'adfff92d-a463-5a31-8ff1-ab4ac5d19389'::uuid, 'À 14 ans, quelle est la priorité en musculation ?', 'mcq', '["Apprendre le geste juste avant d’ajouter de la charge","Soulever le plus lourd possible","S’entraîner chaque jour sans exception","Prendre des protéines en poudre"]'::jsonb, 0, 'Le squelette finit de grandir et ses cartilages de croissance sont fragiles : technique, poids du corps et charges légères, jamais de charge maximale.', 7),
    ('24820bd4-66f3-5af0-ad5c-ed264ea3361b'::uuid, 'adfff92d-a463-5a31-8ff1-ab4ac5d19389'::uuid, 'Au début d’un entraînement de force, les progrès rapides viennent surtout…', 'mcq', '["du système nerveux, qui apprend à recruter plus de fibres en même temps","de muscles qui ont déjà grossi","d’une alimentation plus riche","de la chance"]'::jsonb, 0, 'Les premières semaines, le cerveau commande mieux les fibres existantes : la force monte avant que le muscle ne grossisse.', 8),
    ('07dfdd33-2f66-5dcc-b123-b9e4025cd719'::uuid, 'adfff92d-a463-5a31-8ff1-ab4ac5d19389'::uuid, 'De quoi un muscle a-t-il besoin pour se reconstruire après l’effort ?', 'mcq', '["De protéines, de sommeil et de repos","De sucre uniquement","De courbatures","D’anabolisants"]'::jsonb, 0, 'Les protéines apportent les briques, le sommeil et le repos donnent le temps : les trois ensemble, sinon rien ne se construit.', 9),
    ('8b64d67d-7a6d-5223-92a2-94fde0686fde'::uuid, 'adfff92d-a463-5a31-8ff1-ab4ac5d19389'::uuid, 'Les anabolisants sont interdits et dangereux pour le cœur et les hormones.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Ce sont des hormones de synthèse : interdites par la loi et par l’antidopage, elles abîment le cœur, le foie et le système hormonal, et bloquent la croissance.', 10),
    ('0b1f6c8a-bca9-5549-91b9-66718a3b284f'::uuid, 'adfff92d-a463-5a31-8ff1-ab4ac5d19389'::uuid, 'Qu’appelle-t-on la surcompensation ?', 'mcq', '["La fibre se reconstruit un peu plus épaisse qu’avant l’effort","Un excès d’entraînement qui épuise","Une crampe qui dure plusieurs jours","Le gonflement du muscle pendant la séance"]'::jsonb, 0, 'Après la réparation, le muscle reconstruit « par anticipation », un peu au-dessus de son niveau de départ : c’est ce surplus qui fait progresser.', 11),
    ('50b15b19-61f8-5f5c-a315-d97f9efcc357'::uuid, 'adfff92d-a463-5a31-8ff1-ab4ac5d19389'::uuid, 'Le muscle gonflé juste après une séance (la congestion), c’est…', 'mcq', '["temporaire : du sang et de l’eau, pas du muscle en plus","définitif : le muscle vient de grossir","dangereux : il faut arrêter","le signe d’une blessure"]'::jsonb, 0, 'Pendant l’effort, le sang afflue : le muscle paraît plus gros pendant une heure, puis revient à sa taille. Le vrai gain vient des jours suivants.', 12),
    ('d719b8c7-f8b7-5261-baaa-fcf1288445c6'::uuid, '2f41fedf-53e6-5927-bbc8-596c22a1b8a6'::uuid, 'Que mesure la VO2max ?', 'mcq', '["La vitesse maximale en sprint","Le nombre de battements du cœur au repos","La quantité maximale d’oxygène que le corps peut utiliser par minute","La force maximale des jambes"]'::jsonb, 2, 'La VO2max est la quantité maximale d’oxygène utilisée par minute, exprimée en ml/min/kg.', 1),
    ('6e04b9c8-8294-501c-a513-54e6484131ef'::uuid, '2f41fedf-53e6-5927-bbc8-596c22a1b8a6'::uuid, 'Que signifie le sigle VMA ?', 'mcq', '["Vitesse maximale aérobie","Volume musculaire accéléré","Variation maximale d’allure","Vitesse moyenne annuelle"]'::jsonb, 0, 'La VMA est la vitesse de course à laquelle on atteint sa VO2max, exprimée en km/h.', 2),
    ('3aa5216c-4c90-5319-894a-152178e803d3'::uuid, '2f41fedf-53e6-5927-bbc8-596c22a1b8a6'::uuid, 'Une VMA de 12 km/h correspond à un kilomètre en…', 'mcq', '["5 minutes","4 minutes","6 minutes","7 minutes"]'::jsonb, 0, 'On divise 60 minutes par 12 km/h : 60 ÷ 12 = 5 minutes par kilomètre.', 3),
    ('d3e2b54e-8ab7-5465-a409-ca2a378219e4'::uuid, '2f41fedf-53e6-5927-bbc8-596c22a1b8a6'::uuid, 'Quelle valeur de VO2max est typique d’un adolescent en bonne santé ?', 'mcq', '["Environ 80 à 90 ml/min/kg","Environ 150 ml/min/kg","Environ 5 à 10 ml/min/kg","Environ 40 à 50 ml/min/kg"]'::jsonb, 3, 'Un adolescent en bonne santé tourne autour de 40 à 50 ; les meilleurs coureurs et cyclistes atteignent 80 à 90.', 4),
    ('1eb2a867-40f0-5923-b95e-2a521cf0cac3'::uuid, '2f41fedf-53e6-5927-bbc8-596c22a1b8a6'::uuid, 'L’endurance fondamentale se travaille à environ…', 'mcq', '["150 % de la VMA","60 à 70 % de la VMA","100 à 110 % de la VMA","30 % de la VMA"]'::jsonb, 1, 'L’endurance fondamentale est une allure confortable, entre 60 et 70 % de la VMA, où l’on peut encore parler.', 5),
    ('28a1479c-27d4-5127-9d88-6259c19c2b0a'::uuid, '2f41fedf-53e6-5927-bbc8-596c22a1b8a6'::uuid, 'Avec une VMA de 12 km/h, à quelle vitesse court-on un fractionné à 100 % de VMA ?', 'mcq', '["8 km/h","6 km/h","12 km/h","20 km/h"]'::jsonb, 2, '100 % de 12 km/h, c’est 12 km/h : l’allure du fractionné part de la VMA elle-même.', 6),
    ('63dcd64e-f417-5818-a37c-19fb93bbae77'::uuid, '2f41fedf-53e6-5927-bbc8-596c22a1b8a6'::uuid, 'Pour progresser en endurance, la meilleure recette est surtout…', 'mcq', '["Du fractionné tous les jours","Ne jamais courir lentement","Beaucoup de volume lent et un peu de fractionné","Uniquement des sprints de 10 secondes"]'::jsonb, 2, 'Le volume lent bâtit la base sans fatiguer ; un peu de fractionné fait monter la VMA.', 7),
    ('2fbef096-cd5d-5884-ad93-94aed3ee77c7'::uuid, '2f41fedf-53e6-5927-bbc8-596c22a1b8a6'::uuid, 'Kelvin Kiptum a établi le record du monde du marathon à Chicago en 2023.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le 8 octobre 2023, il a couru en 2 h 00 min 35 s, record officiel du marathon masculin.', 8),
    ('1f4b7961-9430-5bb0-bb40-02324c424f4a'::uuid, '2f41fedf-53e6-5927-bbc8-596c22a1b8a6'::uuid, 'La course d’Eliud Kipchoge sous les 2 heures à Vienne en 2019 est un record du monde officiel.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle était hors des règles des compétitions (meneurs relayés, équipement spécial) : elle ne compte pas comme record officiel.', 9),
    ('173a4b39-e854-595a-bd65-ea410829a0de'::uuid, '2f41fedf-53e6-5927-bbc8-596c22a1b8a6'::uuid, 'Comment passe-t-on d’une vitesse en km/h à un temps au kilomètre ?', 'mcq', '["On ajoute 60 à la vitesse","On divise 60 par la vitesse","On multiplie la vitesse par 60","On soustrait 60 à la vitesse"]'::jsonb, 1, 'Un kilomètre à 10 km/h dure 60 ÷ 10 = 6 minutes : la division fait passer de la vitesse au temps.', 10),
    ('d53a8f85-e842-578c-9808-e5c0486c685f'::uuid, '2f41fedf-53e6-5927-bbc8-596c22a1b8a6'::uuid, 'Courir plus vite à l’endurance fondamentale bâtit mieux la base.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Trop vite, on s’épuise sans bâtir la base : l’endurance fondamentale doit rester une allure où l’on peut parler.', 11),
    ('b6b179f6-c2c2-5f16-83f1-c7d837842f09'::uuid, '2f41fedf-53e6-5927-bbc8-596c22a1b8a6'::uuid, 'Quel test de terrain permet d’estimer sa VMA ?', 'mcq', '["La flexion du tronc","La navette de 20 mètres de Luc Léger","Le saut en longueur sans élan","Le lancer de poids"]'::jsonb, 1, 'On accélère par paliers au rythme de bips jusqu’à ne plus pouvoir suivre : le dernier palier tenu donne la VMA.', 12),
    ('39bb6a9e-7308-5580-850f-12817a7a5cf5'::uuid, 'dcdec29a-e4f3-558b-9c93-73865f38396f'::uuid, 'Dans le cycle de l’entraînement, que désigne la surcompensation ?', 'mcq', '["La fatigue juste après l’effort","Le corps reconstruit un peu au-dessus de son niveau de départ","Un excès d’entraînement","Une douleur musculaire"]'::jsonb, 1, 'Après la réparation, le corps reconstruit un peu plus fort qu’avant : c’est cette marche gagnée qui fait progresser.', 1),
    ('69d4bf26-3f0c-546b-9e9c-1dc6a2a47215'::uuid, 'dcdec29a-e4f3-558b-9c93-73865f38396f'::uuid, 'Combien d’heures de sommeil conseille-t-on entre 14 et 17 ans ?', 'mcq', '["4 à 5 heures","12 à 14 heures","8 à 10 heures","6 heures exactement"]'::jsonb, 2, 'À cet âge, le corps grandit et se répare beaucoup : 8 à 10 heures par nuit.', 2),
    ('e11135f8-69b6-53ea-9681-ad7858c3c828'::uuid, 'dcdec29a-e4f3-558b-9c93-73865f38396f'::uuid, 'Quelle hormone est sécrétée pendant le sommeil profond et aide à réparer les muscles ?', 'mcq', '["L’insuline","L’hormone de croissance","La mélatonine","L’adrénaline"]'::jsonb, 1, 'L’hormone de croissance est sécrétée surtout pendant le sommeil profond : le sommeil fait partie de l’entraînement.', 3),
    ('76a7fcd6-8dd0-5f08-a38b-70bb8b19400f'::uuid, 'dcdec29a-e4f3-558b-9c93-73865f38396f'::uuid, 'Pourquoi les écrans retardent-ils l’endormissement ?', 'mcq', '["Ils font monter la température du corps","Leur lumière bloque la mélatonine, l’hormone du sommeil","Ils produisent des protéines","Ils fatiguent les muscles"]'::jsonb, 1, 'La lumière des écrans empêche la sécrétion de mélatonine, qui donne le signal de dormir.', 4),
    ('8ff4e60a-249f-51bd-817d-452d654d1043'::uuid, 'dcdec29a-e4f3-558b-9c93-73865f38396f'::uuid, 'Après l’effort, dans quel délai est-il conseillé de manger glucides et protéines ?', 'mcq', '["Au bout de six heures","Seulement le lendemain","Dans les deux heures","Jamais : il vaut mieux jeûner"]'::jsonb, 2, 'Dans les deux heures, les glucides refont les réserves et les protéines aident à réparer.', 5),
    ('685fefab-7ad9-5eec-a07c-be8acdb50915'::uuid, 'dcdec29a-e4f3-558b-9c93-73865f38396f'::uuid, 'Un jour de repos est un jour perdu pour la progression.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le repos est le moment où la surcompensation se construit : il fait partie du programme.', 6),
    ('4713f3ff-a43f-5ccb-932d-636afd61c95a'::uuid, 'dcdec29a-e4f3-558b-9c93-73865f38396f'::uuid, 'Que fait-on pour la récupération active ?', 'mcq', '["On bouge doucement : marche ou vélo tranquille","On reste couché toute la journée","On refait une séance intense","On saute le repas"]'::jsonb, 0, 'Bouger doucement aide à se sentir mieux sans réentraîner les muscles fatigués.', 7),
    ('860ac95d-1916-583c-85c9-06aa101b24fb'::uuid, 'dcdec29a-e4f3-558b-9c93-73865f38396f'::uuid, 'Lequel de ces signes peut indiquer un surentraînement ?', 'mcq', '["Une envie de courir plus longtemps","Un appétit stable","Une fréquence cardiaque de repos qui monte","Des courbatures légères après un effort"]'::jsonb, 2, 'Fatigue persistante, cœur qui s’emballe au repos, sommeil cassé et performances en baisse sont des signaux d’alerte.', 8),
    ('3d45159a-5273-50b2-b453-7d90f6284194'::uuid, 'dcdec29a-e4f3-558b-9c93-73865f38396f'::uuid, 'Face à un surentraînement, la bonne réponse est de s’entraîner davantage.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il faut récupérer, pas en faire plus : le corps a besoin de temps pour se reconstruire.', 9),
    ('a78130a2-ac14-5d05-b04b-0bbcd0de3819'::uuid, 'dcdec29a-e4f3-558b-9c93-73865f38396f'::uuid, 'Que sait-on des étirements contre les courbatures ?', 'mcq', '["Ils sont agréables, mais leur effet n’est pas prouvé","Ils les aggravent toujours","Ils remplacent le sommeil","Ils les suppriment toujours"]'::jsonb, 0, 'Les étirements font du bien, mais aucune preuve solide ne montre qu’ils évitent les courbatures.', 10),
    ('4358fb21-764f-53d0-860d-e8b4a0800c20'::uuid, 'dcdec29a-e4f3-558b-9c93-73865f38396f'::uuid, 'S’entraîner avant la fin de la réparation permet de progresser plus vite.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Réentraîner un corps pas encore réparé, c’est partir d’un niveau plus bas : rien n’est gagné.', 11),
    ('eae52615-c7f4-5f72-bb15-8ba13b8d1ab4'::uuid, 'dcdec29a-e4f3-558b-9c93-73865f38396f'::uuid, 'Quel effet ont le froid et le massage sur la récupération ?', 'mcq', '["Un effet dangereux","Un effet immédiat et total","Aucun effet sur le bien-être","Un effet modeste"]'::jsonb, 3, 'Ils font du bien sans remplacer le sommeil, le repos et l’assiette.', 12),
    ('ffe71d5a-4525-5385-862f-f53eb362797f'::uuid, 'd84ba2cd-62d9-5661-8bc7-11cd184270fe'::uuid, 'Combien de temps dure un échauffement efficace ?', 'mcq', '["Une heure","30 secondes","Aucun temps : on s’échauffe en jouant","10 à 15 minutes"]'::jsonb, 3, 'Dix à quinze minutes suffisent à préparer cœur, articulations et gestes du sport.', 1),
    ('6261591c-9048-544b-9aa7-254aa68ceb41'::uuid, 'd84ba2cd-62d9-5661-8bc7-11cd184270fe'::uuid, 'Dans quel ordre se déroule un bon échauffement ?', 'mcq', '["Gestes à vitesse maximale, puis cardio","Cardio léger, mobilité, puis gestes spécifiques accélérés","Étirements longs, puis sprint, puis repos","Aucun ordre particulier"]'::jsonb, 1, 'On monte progressivement : d’abord le cœur et les articulations, ensuite les gestes du sport de plus en plus vite.', 2),
    ('474928e7-54a2-56d2-9482-28f5da95a909'::uuid, 'd84ba2cd-62d9-5661-8bc7-11cd184270fe'::uuid, 'Que réduit environ d’un tiers le programme FIFA 11+ chez les jeunes footballeurs ?', 'mcq', '["Le temps de jeu","Le nombre de buts","Les blessures","Les fautes sifflées"]'::jsonb, 2, 'Pratiqué régulièrement, ce programme d’échauffement diminue les blessures d’environ un tiers.', 3),
    ('bd158c69-0a58-5bc4-9496-3f54888ffb62'::uuid, 'd84ba2cd-62d9-5661-8bc7-11cd184270fe'::uuid, 'Quel type d’étirement fait-on plutôt avant l’effort ?', 'mcq', '["Aucun étirement jamais","Statique, tenu une minute","Dynamique, en mouvement","Forcé jusqu’à la douleur"]'::jsonb, 2, 'Les mouvements amples préparent les articulations sans diminuer la force.', 4),
    ('83c7f676-b66b-5a04-b355-8eadc9c89ca6'::uuid, 'd84ba2cd-62d9-5661-8bc7-11cd184270fe'::uuid, 'Les étirements statiques longs avant l’effort préviennent les blessures.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Avant l’effort, ils diminuent la force un moment et ne préviennent pas les blessures : on les garde pour après.', 5),
    ('0facee2a-6e06-5b01-ae1a-d5a0ff78a074'::uuid, 'd84ba2cd-62d9-5661-8bc7-11cd184270fe'::uuid, 'À quoi sert surtout le gainage ?', 'mcq', '["À prendre du poids","À gagner en souplesse","À courir plus vite","À protéger le dos"]'::jsonb, 3, 'Planche et gainage latéral renforcent les muscles profonds qui soutiennent la colonne.', 6),
    ('14a074ad-7364-5385-83cd-d712695c169d'::uuid, 'd84ba2cd-62d9-5661-8bc7-11cd184270fe'::uuid, 'Quel exercice travaille la proprioception de la cheville ?', 'mcq', '["Soulever une charge lourde","S’étirer les bras","Tenir en équilibre sur un pied","Courir en ligne droite"]'::jsonb, 2, 'Tenir sur un pied, yeux ouverts puis fermés, entraîne la cheville à corriger les déséquilibres.', 7),
    ('5e1575b2-ae78-5ce7-99e3-e1304584aa8b'::uuid, 'd84ba2cd-62d9-5661-8bc7-11cd184270fe'::uuid, 'De combien peut-on augmenter la charge d’entraînement d’une semaine à l’autre, selon la règle courante ?', 'mcq', '["Autant qu’on veut","De 100 %","Pas plus de 10 %","De 50 %"]'::jsonb, 2, 'La progressivité protège les tendons et les os : pas plus de 10 % en plus d’une semaine à l’autre.', 8),
    ('ee10461e-4b6a-566b-b2b0-6607c63a681a'::uuid, 'd84ba2cd-62d9-5661-8bc7-11cd184270fe'::uuid, 'La maladie d’Osgood-Schlatter touche surtout…', 'mcq', '["l’épaule des nageurs adultes","le genou, entre 10 et 15 ans","le poignet, après 60 ans","le dos des enfants de 3 ans"]'::jsonb, 1, 'C’est une douleur de croissance sous le genou, fréquente entre 10 et 15 ans.', 9),
    ('051b7950-765a-5246-8938-2d1a0197cdcb'::uuid, 'd84ba2cd-62d9-5661-8bc7-11cd184270fe'::uuid, 'Que fait-on devant une douleur de croissance comme celle de Sever au talon ?', 'mcq', '["On l’ignore","On supprime tout le sport pour toujours","On adapte l’activité sans forcer","On double l’entraînement"]'::jsonb, 2, 'Moins de sauts, moins de sol dur : on adapte, et la douleur passe avec le temps.', 10),
    ('33e5e8be-4f2d-5fa1-a513-d0615d25ef7a'::uuid, 'd84ba2cd-62d9-5661-8bc7-11cd184270fe'::uuid, 'Une douleur qui dure plusieurs jours doit être ignorée pour continuer à progresser.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Une douleur qui dure ou qui augmente mérite l’avis d’un médecin : on n’avance pas malgré la douleur.', 11),
    ('d386b98f-19b6-5ad7-8434-343084ebe1f2'::uuid, 'd84ba2cd-62d9-5661-8bc7-11cd184270fe'::uuid, 'Qu’est-ce que la proprioception ?', 'mcq', '["Savoir où sont ses articulations sans les regarder","La capacité à courir longtemps","La souplesse du dos","La puissance d’un sprint"]'::jsonb, 0, 'C’est le sens de la position du corps, qui permet à la cheville de corriger un faux pas avant la torsion.', 12),
    ('a8b8515b-875f-52cf-a2a2-2a5bbf9c9900'::uuid, '07a22c4a-a740-5d75-83a8-7f17f91f67c9'::uuid, 'Où et quand le CIO est-il créé ?', 'mcq', '["À la Sorbonne, à Paris, le 23 juin 1894","À Athènes, en 1896","À Londres, en 1908","À Berlin, en 1936"]'::jsonb, 0, 'Le congrès de la Sorbonne crée le CIO le 23 juin 1894 ; les premiers Jeux ont lieu deux ans plus tard à Athènes.', 1),
    ('7d29647c-ddb2-5d96-b20e-4e818624ff6c'::uuid, '07a22c4a-a740-5d75-83a8-7f17f91f67c9'::uuid, 'Quelle ville accueille les premiers Jeux olympiques modernes en 1896 ?', 'mcq', '["New York","Rome","Athènes","Paris"]'::jsonb, 2, 'Les premiers Jeux modernes se tiennent à Athènes en 1896, en hommage à la Grèce antique.', 2),
    ('14867027-43a2-5ce3-8584-587a717b6404'::uuid, '07a22c4a-a740-5d75-83a8-7f17f91f67c9'::uuid, 'Qui est à l’origine de la devise « Citius, Altius, Fortius » ?', 'mcq', '["Le dominicain Henri Didon","Alice Milliat","Jules Rimet","Pierre de Coubertin seul"]'::jsonb, 0, 'Henri Didon la lance en 1891 ; Coubertin l’adopte ensuite pour les Jeux.', 3),
    ('6d0bc287-864d-5377-9c05-aa4d4a3e7321'::uuid, '07a22c4a-a740-5d75-83a8-7f17f91f67c9'::uuid, 'Que veut dire « Citius, Altius, Fortius » ?', 'mcq', '["Plus vite, plus haut, plus fort","Plus tôt, plus tard, plus loin","Ensemble, unis, solidaires","Gagner, jouer, participer"]'::jsonb, 0, 'C’est la devise latine des Jeux : plus vite, plus haut, plus fort.', 4),
    ('fcc90033-0dff-5ce5-8ea2-3af791ef268c'::uuid, '07a22c4a-a740-5d75-83a8-7f17f91f67c9'::uuid, 'Quel est le plus vieux club sportif français cité par l’histoire du sport ?', 'mcq', '["Le Havre Athletic Club, créé en 1872","L’Olympique de Marseille, créé en 1899","Le Paris Saint-Germain, créé en 1970","Le Stade de France, créé en 1998"]'::jsonb, 0, 'Le Havre Athletic Club, fondé en 1872, est considéré comme le plus vieux club français.', 5),
    ('09ce7601-e4c3-5552-8f81-5c4778eb5568'::uuid, '07a22c4a-a740-5d75-83a8-7f17f91f67c9'::uuid, 'Coubertin était favorable à la compétition sportive féminine.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il était opposé au sport féminin de compétition : c’est l’une de ses limites, que les femmes ont dû combattre.', 6),
    ('2429fc3c-3140-520c-9119-8797e3b1bbac'::uuid, '07a22c4a-a740-5d75-83a8-7f17f91f67c9'::uuid, 'Que crée Alice Milliat à Paris en 1922 ?', 'mcq', '["Le CIO","Les Jeux mondiaux féminins","La Coupe du monde de football","Le Tour de France"]'::jsonb, 1, 'Alice Milliat organise les premiers Jeux mondiaux féminins pour que les femmes puissent concourir.', 7),
    ('a6750d4d-c752-5f8c-9780-76be24baa5e9'::uuid, '07a22c4a-a740-5d75-83a8-7f17f91f67c9'::uuid, 'Qui est à l’origine de la Coupe du monde de football, jouée pour la première fois en 1930 ?', 'mcq', '["Jules Rimet, président de la FIFA","Pierre de Coubertin","Thomas Arnold","Henri Didon"]'::jsonb, 0, 'Jules Rimet, président de la FIFA, imagine le tournoi mondial, joué en Uruguay en 1930.', 8),
    ('ac9649e6-c181-5a82-bad3-86374608d840'::uuid, '07a22c4a-a740-5d75-83a8-7f17f91f67c9'::uuid, 'Le modèle d’éducation par le sport que Coubertin admire vient…', 'mcq', '["Des écoles de Sparte antique","D’une académie japonaise","D’une université américaine","Des écoles anglaises comme Rugby School"]'::jsonb, 3, 'Coubertin admire l’école anglaise, où Thomas Arnold fait du sport un moyen de former le caractère.', 9),
    ('b52c97c0-f363-5af9-b4b7-5f130538de2f'::uuid, '07a22c4a-a740-5d75-83a8-7f17f91f67c9'::uuid, 'La phrase « L’important n’est pas le triomphe mais le combat » est une invention de Coubertin sans autre origine.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Coubertin la cite en 1908 en reprenant un propos de l’évêque Ethelbert Talbot.', 10),
    ('0445364d-68ce-50d3-b8da-c25b2c00036e'::uuid, '07a22c4a-a740-5d75-83a8-7f17f91f67c9'::uuid, 'Que fait l’USFSA, créée en 1887 ?', 'mcq', '["Elle gère la Coupe du monde","Elle organise les Jeux olympiques","Elle fabrique du matériel sportif","Elle fédère des sociétés sportives françaises"]'::jsonb, 3, 'L’USFSA rassemble les sociétés sportives françaises : un pas vers le sport organisé.', 11),
    ('cd29c203-529e-5e7d-95d9-a96ce2ee4079'::uuid, '07a22c4a-a740-5d75-83a8-7f17f91f67c9'::uuid, 'Les premiers Jeux mondiaux féminins ont eu lieu à Paris.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Alice Milliat les a organisés à Paris en 1922, avec des athlètes de plusieurs pays.', 12),
    ('ae1603ad-eb27-5837-b443-886457ed6068'::uuid, 'f683dabb-947d-5fdd-82d9-d8d11961d700'::uuid, 'En quelle année le Tour de France est-il créé ?', 'mcq', '["1952","1919","1903","1985"]'::jsonb, 2, 'Le journal L’Auto lance la première édition en 1903, avec 6 étapes et 2 428 km.', 1),
    ('0d42b965-beb8-5531-b4e6-0d9ccb96185e'::uuid, 'f683dabb-947d-5fdd-82d9-d8d11961d700'::uuid, 'Pourquoi le journal L’Auto a-t-il créé le Tour de France ?', 'mcq', '["Pour fêter une victoire militaire","Pour promouvoir un fabricant de vélos","Pour vendre davantage de journaux","Pour former des champions olympiques"]'::jsonb, 2, 'Desgrange et L’Auto cherchaient à augmenter leurs ventes : la course était d’abord une opération de presse.', 2),
    ('7aa70008-8c6f-5fe4-ba9e-2cf06436fd1a'::uuid, 'f683dabb-947d-5fdd-82d9-d8d11961d700'::uuid, 'Qui a gagné la toute première édition du Tour ?', 'mcq', '["Maurice Garin","Bernard Hinault","Miguel Indurain","Eddy Merckx"]'::jsonb, 0, 'Maurice Garin remporte le Tour de 1903, sur 6 étapes et 2 428 km.', 3),
    ('5a48c188-1fc8-53f3-b9b2-137e714046e0'::uuid, 'f683dabb-947d-5fdd-82d9-d8d11961d700'::uuid, 'Pourquoi le maillot du leader est-il jaune ?', 'mcq', '["Parce que le soleil brille en juillet","Parce que le jaune se voit de loin","Parce que c’est la couleur de la France","Parce que le journal L’Auto était imprimé sur du papier jaune"]'::jsonb, 3, 'La couleur reprend celle du papier du journal organisateur ; le maillot jaune apparaît en 1919.', 4),
    ('1cd02312-f07f-5e01-86a6-40130dc99c9b'::uuid, 'f683dabb-947d-5fdd-82d9-d8d11961d700'::uuid, 'Quel maillot récompense le meilleur grimpeur ?', 'mcq', '["Le maillot blanc","Le maillot à pois","Le maillot vert","Le maillot jaune"]'::jsonb, 1, 'Le maillot à pois est celui du meilleur grimpeur ; le vert va au sprinteur et le blanc au meilleur jeune.', 5),
    ('8305af2c-bfe5-5a1f-b842-9773d62ef3b1'::uuid, 'f683dabb-947d-5fdd-82d9-d8d11961d700'::uuid, 'Quel est le dernier Français vainqueur du Tour de France ?', 'mcq', '["Laurent Fignon, en 2000","Jacques Anquetil, en 1964","Bernard Hinault, en 1985","Richard Virenque, en 1999"]'::jsonb, 2, 'Bernard Hinault l’a emporté en 1985 : depuis, aucun Français n’a gagné.', 6),
    ('c9174ca1-1226-5e19-bd86-733e4b547049'::uuid, 'f683dabb-947d-5fdd-82d9-d8d11961d700'::uuid, 'Que s’est-il passé pour Lance Armstrong en 2012 ?', 'mcq', '["Il a pris sa retraite sportive","Il a été élu président de l’UCI","Il a été déchu de ses sept Tours pour dopage","Il a gagné un huitième Tour"]'::jsonb, 2, 'Reconnu coupable de dopage, il a perdu ses sept victoires.', 7),
    ('404dee3a-c672-524c-bf67-fc1f56bea135'::uuid, 'f683dabb-947d-5fdd-82d9-d8d11961d700'::uuid, 'Combien d’étapes compte le Tour de France actuel ?', 'mcq', '["21","3","60","6"]'::jsonb, 0, 'Le Tour actuel compte 21 étapes en juillet, pour environ 3 400 km.', 8),
    ('2e134285-36b8-571b-a263-0b15bfcd772f'::uuid, 'f683dabb-947d-5fdd-82d9-d8d11961d700'::uuid, 'Le Tour de France Femmes existe depuis 2022.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Il a été lancé en 2022 ; Pauline Ferrand-Prévot l’a gagné en 2025.', 9),
    ('80c9d602-6a89-52ec-b01f-b30ef4014eda'::uuid, 'f683dabb-947d-5fdd-82d9-d8d11961d700'::uuid, 'Le Tour de France est né pour un but sportif sans lien avec l’argent.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est une idée de journal pour vendre du papier : la presse est à l’origine de la course.', 10),
    ('b435dcb9-8f63-5c38-8808-3c0412bd1c3f'::uuid, 'f683dabb-947d-5fdd-82d9-d8d11961d700'::uuid, 'Qui a remporté le Tour de France en 2024 et 2025 ?', 'mcq', '["Eddy Merckx","Tadej Pogačar","Miguel Indurain","Bernard Hinault"]'::jsonb, 1, 'Pogačar l’a emporté en 2020, 2021, 2024 et 2025.', 11),
    ('73709d51-76ce-5632-8b6d-abf4612877f4'::uuid, 'f683dabb-947d-5fdd-82d9-d8d11961d700'::uuid, 'Que crie Octave Lapize aux organisateurs au Tourmalet en 1910 ?', 'mcq', '["« Encore un tour ! »","« Vous êtes des assassins ! »","« Vive la France ! »","« Je suis le meilleur ! »"]'::jsonb, 1, 'Épuisé par l’ascension, il dénonce la dureté de l’étape : la montagne devient un mythe du Tour.', 12),
    ('f80a7cf0-0cd9-5809-a52f-78a1b6cfcdea'::uuid, '41938d96-4d57-58b3-b9ac-0bf938892ab6'::uuid, 'Quel est le score de la finale de la Coupe du monde 1998 ?', 'mcq', '["France 3 – Brésil 0","France 2 – Brésil 1","France 4 – Brésil 2","France 1 – Brésil 0"]'::jsonb, 0, 'La France bat le Brésil 3-0 au Stade de France, le 12 juillet 1998.', 1),
    ('cdbc9428-bd07-524c-a527-25f397a9d8bb'::uuid, '41938d96-4d57-58b3-b9ac-0bf938892ab6'::uuid, 'Qui marque deux buts de la tête lors de la finale 1998 ?', 'mcq', '["Michel Platini","Didier Deschamps","Kylian Mbappé","Zinédine Zidane"]'::jsonb, 3, 'Zidane marque deux fois de la tête, avant le but de Petit.', 2),
    ('a5163dc5-d76f-51bf-a244-0822414881b4'::uuid, '41938d96-4d57-58b3-b9ac-0bf938892ab6'::uuid, 'Qui est le sélectionneur de l’équipe de France championne du monde en 1998 ?', 'mcq', '["Aimé Jacquet","Michel Hidalgo","Raymond Domenech","Didier Deschamps"]'::jsonb, 0, 'Aimé Jacquet dirige les Bleus de 1998 ; Deschamps en sera le capitaine puis, plus tard, le sélectionneur.', 3),
    ('b48eb305-92b9-5b77-9685-f173d81af6a9'::uuid, '41938d96-4d57-58b3-b9ac-0bf938892ab6'::uuid, 'Combien de buts Michel Platini a-t-il marqués à l’Euro 1984 ?', 'mcq', '["3","12","5","9"]'::jsonb, 3, 'Il marque 9 buts pendant le tournoi, un record, et la France gagne à domicile.', 4),
    ('fd9f60d9-fb50-56d0-b7b2-bf264f732545'::uuid, '41938d96-4d57-58b3-b9ac-0bf938892ab6'::uuid, 'Contre quelle équipe la France gagne-t-elle la finale de la Coupe du monde 2018 ?', 'mcq', '["L’Argentine","Le Brésil","L’Italie","La Croatie"]'::jsonb, 3, 'La France bat la Croatie 4-2 à Moscou, le 15 juillet 2018.', 5),
    ('80c0bc29-24c9-58ba-86a1-72cf228af328'::uuid, '41938d96-4d57-58b3-b9ac-0bf938892ab6'::uuid, 'Quelle est la particularité de Didier Deschamps ?', 'mcq', '["Champion du monde comme joueur en 1998 et comme sélectionneur en 2018","Meilleur buteur de l’Euro 1984","Auteur d’un triplé en finale 2022","Fondateur du centre de Clairefontaine"]'::jsonb, 0, 'Il a soulevé la Coupe du monde deux fois, d’abord sur le terrain, ensuite sur le banc.', 6),
    ('aab6928b-ad30-52eb-a9b9-5dbd19dc1992'::uuid, '41938d96-4d57-58b3-b9ac-0bf938892ab6'::uuid, 'La finale de la Coupe du monde 2006 a été perdue par la France aux tirs au but.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Elle est restée célèbre aussi pour le coup de tête de Zidane, qui a été expulsé.', 7),
    ('484a649f-8271-5cfc-b363-ab813219bbf4'::uuid, '41938d96-4d57-58b3-b9ac-0bf938892ab6'::uuid, 'Quel joueur marque un triplé en finale de la Coupe du monde 2022 ?', 'mcq', '["Zinédine Zidane","Olivier Giroud","Antoine Griezmann","Kylian Mbappé"]'::jsonb, 3, 'Mbappé marque trois buts (3-3), mais l’Argentine gagne aux tirs au but.', 8),
    ('4bc28bbc-71e7-516e-a5cd-3cfb20a85cdf'::uuid, '41938d96-4d57-58b3-b9ac-0bf938892ab6'::uuid, 'Que représente le centre de Clairefontaine, ouvert en 1988 ?', 'mcq', '["Le siège du CIO","Une école d’arbitrage","La formation des meilleurs jeunes footballeurs français","Un stade de 80 000 places"]'::jsonb, 2, 'Clairefontaine est le centre national de formation du football français.', 9),
    ('bf9e68fa-a2bb-52c6-9fe3-88acb9f93e42'::uuid, '41938d96-4d57-58b3-b9ac-0bf938892ab6'::uuid, 'En 2025, le PSG est devenu le premier club français champion d’Europe depuis l’OM en 1993.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le PSG a battu l’Inter 5-0 à Munich, le 31 mai 2025.', 10),
    ('aa2087eb-e6bf-5aef-afbc-4194368c4086'::uuid, '41938d96-4d57-58b3-b9ac-0bf938892ab6'::uuid, 'La France a remporté la Coupe du monde 2022 en battant l’Argentine.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La finale s’est terminée 3-3, puis l’Argentine l’a emporté aux tirs au but.', 11),
    ('df5f07f1-3874-5ae1-8869-50ca037feaac'::uuid, '41938d96-4d57-58b3-b9ac-0bf938892ab6'::uuid, 'Quel résultat l’équipe de France féminine a-t-elle obtenu à l’Euro 2022 ?', 'mcq', '["Une médaille d’or","Une élimination au premier tour","Une victoire en finale","Une demi-finale"]'::jsonb, 3, 'Les Bleues ont atteint les demi-finales de l’Euro 2022.', 12),
    ('d85b7da9-b9d5-58f9-b1ad-4d387b60190d'::uuid, 'b00c13c3-b4bc-5c0e-84d8-0614d09fc8f4'::uuid, 'Pendant quelle manifestation se tiennent les Jeux de Paris en 1900 ?', 'mcq', '["La Coupe du monde de football","L’Exposition universelle","Un congrès du CIO","Le Tour de France"]'::jsonb, 1, 'Les Jeux de 1900 sont noyés dans l’Exposition universelle et durent cinq mois.', 1),
    ('01c1f47e-59ae-526a-8930-68e64202ca20'::uuid, 'b00c13c3-b4bc-5c0e-84d8-0614d09fc8f4'::uuid, 'Qui est la première championne olympique de l’histoire, en 1900 ?', 'mcq', '["Marie-José Pérec, en athlétisme","Alice Milliat, en athlétisme","Charlotte Cooper, au tennis","Laure Manaudou, en natation"]'::jsonb, 2, 'Charlotte Cooper gagne le tournoi de tennis en 1900, l’année où les femmes entrent aux Jeux.', 2),
    ('c6df7679-6966-5faf-99bd-768df732e1cd'::uuid, 'b00c13c3-b4bc-5c0e-84d8-0614d09fc8f4'::uuid, 'Combien de femmes participent aux Jeux de Paris en 1900 ?', 'mcq', '["2","220","2 200","22"]'::jsonb, 3, 'Elles sont 22, une première dans l’histoire olympique.', 3),
    ('0be8c4fa-7968-5bfb-9141-d6dcac8357dd'::uuid, 'b00c13c3-b4bc-5c0e-84d8-0614d09fc8f4'::uuid, 'Quelle nouveauté marque les Jeux de 1924 à Paris ?', 'mcq', '["Le premier village olympique","Le premier match de football","La première cérémonie sur un fleuve","La parité parfaite"]'::jsonb, 0, 'En 1924, les athlètes sont logés dans un village olympique, une première.', 4),
    ('146f493b-230e-537c-8924-94be1951b8d4'::uuid, 'b00c13c3-b4bc-5c0e-84d8-0614d09fc8f4'::uuid, 'Combien de médailles d’or le Finlandais Paavo Nurmi remporte-t-il à Paris en 1924 ?', 'mcq', '["1","10","3","5"]'::jsonb, 3, 'Paavo Nurmi gagne 5 ors en athlétisme, un exploit en une seule édition.', 5),
    ('6cd50f5a-22ee-544b-b882-5679b45a639d'::uuid, 'b00c13c3-b4bc-5c0e-84d8-0614d09fc8f4'::uuid, 'Quel nageur de 1924 jouera ensuite Tarzan au cinéma ?', 'mcq', '["Eddy Merckx","Mark Spitz","Paavo Nurmi","Johnny Weissmuller"]'::jsonb, 3, 'Weissmuller gagne 3 ors à Paris avant de devenir l’acteur le plus célèbre à incarner Tarzan.', 6),
    ('d6b7d7e9-cb96-5145-a130-4cf2519248fa'::uuid, 'b00c13c3-b4bc-5c0e-84d8-0614d09fc8f4'::uuid, 'Où se déroulent en 1924 les premiers Jeux d’hiver reconnus plus tard ?', 'mcq', '["À Grenoble","À Colombes","À Chamonix","À Lyon"]'::jsonb, 2, 'Chamonix a accueilli en 1924 les Jeux d’hiver, reconnus plus tard comme premiers Jeux d’hiver.', 7),
    ('cb8ffa69-b634-5b69-99b5-0671a739c741'::uuid, 'b00c13c3-b4bc-5c0e-84d8-0614d09fc8f4'::uuid, 'Les Jeux de 2024 se sont déroulés du 26 juillet au 11 août.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Ils ont suivi par les Jeux paralympiques, du 28 août au 8 septembre.', 8),
    ('dbe5e92a-27f2-5a72-82b6-304b88a5dfa5'::uuid, 'b00c13c3-b4bc-5c0e-84d8-0614d09fc8f4'::uuid, 'Qu’y a-t-il d’inédit dans la cérémonie d’ouverture des Jeux de 2024 ?', 'mcq', '["Elle a lieu dans un stade vide","Elle est organisée sous terre","Elle ne dure qu’une minute","Elle a lieu sur la Seine et non dans un stade"]'::jsonb, 3, 'La cérémonie se déroule sur la Seine : une première hors d’un stade.', 9),
    ('f9c958b0-d9b8-5715-9870-9808c6ce53fa'::uuid, 'b00c13c3-b4bc-5c0e-84d8-0614d09fc8f4'::uuid, 'Environ quelle part des sites de 2024 était existante ou temporaire ?', 'mcq', '["95 %","10 %","30 %","50 %"]'::jsonb, 0, 'Environ 95 % des sites existaient déjà ou étaient temporaires : peu de constructions neuves.', 10),
    ('8004728b-db3d-5ef8-847c-4b57ede783d1'::uuid, 'b00c13c3-b4bc-5c0e-84d8-0614d09fc8f4'::uuid, 'Aux Jeux de 2024, la France a terminé 5e au tableau des médailles.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Elle se classe cinquième nation, une belle performance à domicile.', 11),
    ('e2e6681b-3a8a-51a7-9791-b13389653d5b'::uuid, 'b00c13c3-b4bc-5c0e-84d8-0614d09fc8f4'::uuid, 'Que sont devenus le village des athlètes de 2024 ?', 'mcq', '["Un parc d’attractions","Un musée de la Seine","Des logements à Saint-Denis et Saint-Ouen","Un stade de rugby"]'::jsonb, 2, 'Le village olympique est transformé en logements, un héritage concret pour les habitants.', 12),
    ('a4c9a0c6-e1a2-5cd9-a199-f76063124701'::uuid, '18cde9ea-f7b1-599e-8432-dda2a630e24b'::uuid, 'Quelle est la première mission de l’arbitre ?', 'mcq', '["Aider l’équipe qui perd","Faire respecter la règle, la même pour tous","Donner de l’ambiance au match","Choisir les joueurs de chaque équipe"]'::jsonb, 1, 'L’arbitre applique la même règle aux deux camps pour que le jeu soit juste.', 1),
    ('53edc61e-fc6d-5508-8bbc-57e6a64d0b1d'::uuid, '18cde9ea-f7b1-599e-8432-dda2a630e24b'::uuid, 'Dans quel sport l’arbitre explique-t-il ses décisions au micro, seul le capitaine pouvant lui parler ?', 'mcq', '["Le cyclisme","Le tennis","La natation","Le rugby"]'::jsonb, 3, 'Au rugby, l’arbitre s’explique et seul le capitaine échange avec lui : moins de contestation.', 2),
    ('23bda312-67e8-5bc7-bb1e-5ec1d3103dcb'::uuid, '18cde9ea-f7b1-599e-8432-dda2a630e24b'::uuid, 'Depuis quelle Coupe du monde le VAR est-il utilisé en football ?', 'mcq', '["1998","2006","2014","2018"]'::jsonb, 3, 'Le VAR débute à la Coupe du monde 2018 ; la goal-line technology date de 2014.', 3),
    ('f20b4589-3df3-5a33-b6f8-c3e2e24d26b0'::uuid, '18cde9ea-f7b1-599e-8432-dda2a630e24b'::uuid, 'Quel cas ne relève PAS de l’intervention du VAR ?', 'mcq', '["Un penalty","Un but","Une erreur d’identité","Un hors-jeu de touche"]'::jsonb, 3, 'Le VAR intervient pour un but, un penalty, un carton rouge direct ou une erreur d’identité, pas pour une touche.', 4),
    ('b244e098-862b-57a0-9fdb-0cfc8d92f733'::uuid, '18cde9ea-f7b1-599e-8432-dda2a630e24b'::uuid, 'Que permet la goal-line technology, utilisée depuis la Coupe du monde 2014 ?', 'mcq', '["Savoir si le ballon a franchi la ligne de but","Mesurer la vitesse des joueurs","Désigner le meilleur joueur","Compter les passes"]'::jsonb, 0, 'Elle signale immédiatement à l’arbitre si le ballon a entièrement franchi la ligne.', 5),
    ('6c127f5e-cc85-5995-b518-671ec648ede5'::uuid, '18cde9ea-f7b1-599e-8432-dda2a630e24b'::uuid, 'Le Hawk-Eye est utilisé au tennis depuis 2006.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Ce système suit la balle et indique si elle est dedans ou dehors.', 6),
    ('5f19353e-03a2-56d8-a796-b19bee1606c2'::uuid, '18cde9ea-f7b1-599e-8432-dda2a630e24b'::uuid, 'Qui conseille Jesse Owens au saut en longueur aux Jeux de Berlin en 1936 ?', 'mcq', '["Pierre de Coubertin","Lutz Long, son rival allemand","Paavo Nurmi","Johnny Weissmuller"]'::jsonb, 1, 'Lutz Long, un adversaire, aide Owens ; c’est un exemple célèbre de fair-play.', 7),
    ('6e35edbb-f36d-526c-968c-1034039aa681'::uuid, '18cde9ea-f7b1-599e-8432-dda2a630e24b'::uuid, 'Que fait Paolo Di Canio en 2000 ?', 'mcq', '["Il refuse de marquer devant un gardien blessé","Il change de maillot en cours de match","Il marque un but de la main","Il quitte le terrain en protestant"]'::jsonb, 0, 'Il attrape le ballon à la main au lieu de profiter d’un gardien au sol.', 8),
    ('b0f0013d-4354-55de-801f-1261b2fa3a8d'::uuid, '18cde9ea-f7b1-599e-8432-dda2a630e24b'::uuid, 'Que fait Iván Fernández pour Abel Mutai en 2012 ?', 'mcq', '["Il le laisse gagner alors que Mutai s’était trompé de ligne d’arrivée","Il lui vole la victoire","Il abandonne la course","Il l’accuse de tricher"]'::jsonb, 0, 'Fernández ralentit et laisse passer Mutai : le geste est resté un symbole du fair-play.', 9),
    ('317444b8-0fe9-5b42-87f9-ec75defaec44'::uuid, '18cde9ea-f7b1-599e-8432-dda2a630e24b'::uuid, 'Le VAR remplace l’arbitre sur le terrain.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'L’arbitre reste le patron : la vidéo l’aide dans quatre cas précis sans le remplacer.', 10),
    ('d324fd23-83b6-56ac-a739-85bf4ed68f76'::uuid, '18cde9ea-f7b1-599e-8432-dda2a630e24b'::uuid, 'Le fair-play, c’est respecter l’adversaire et la règle même quand personne ne regarde.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Il s’agit de jouer juste par choix, même sans arbitre ni caméra.', 11),
    ('1c648474-3447-58ea-967d-e4ca3f3b6c7d'::uuid, '18cde9ea-f7b1-599e-8432-dda2a630e24b'::uuid, 'Pourquoi l’arbitrage par les élèves est-il utile en EPS ?', 'mcq', '["Il permet aux élèves de choisir qui gagne","Il fait comprendre qu’un jeu n’existe que si tous acceptent la règle","Il supprime les règles","Il remplace le professeur"]'::jsonb, 1, 'En arbitrant, on voit le match d’un seul endroit et on mesure la difficulté de décider vite.', 12),
    ('a859b17e-6052-586c-bdc9-dd5b9d6d2c71'::uuid, '73a19821-b4ed-5f4d-9555-ca88a3fbb640'::uuid, 'Que mesure la qualité physique appelée « force » ?', 'mcq', '["L’amplitude d’une articulation","La durée pendant laquelle on peut courir","La tension qu’on peut produire contre une résistance","La rapidité avec laquelle on réagit à un signal"]'::jsonb, 2, 'La force, c’est produire de la tension contre une résistance : soulever, pousser, lancer.', 1),
    ('1f1de1ab-d668-58dd-a844-9958bb2fefca'::uuid, '73a19821-b4ed-5f4d-9555-ca88a3fbb640'::uuid, 'Quelles fibres musculaires fournissent surtout force et vitesse, mais se fatiguent vite ?', 'mcq', '["Les fibres rapides, de type II","Les fibres lentes, de type I","Les fibres du cœur uniquement","Aucune fibre : c’est le squelette"]'::jsonb, 0, 'Les fibres rapides produisent beaucoup de puissance mais s’épuisent vite ; les fibres lentes durent plus longtemps.', 2),
    ('68562d04-2a9a-5537-9f99-69f69f1e9a6a'::uuid, '73a19821-b4ed-5f4d-9555-ca88a3fbb640'::uuid, 'La proportion de fibres lentes et rapides décide de tout : on ne peut pas progresser contre elle.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle est en partie héritée, mais tout s’entraîne : chacun peut progresser dans la force, la vitesse et l’endurance.', 3),
    ('e15c64bb-1ef5-588e-a07f-0a3ba0ac4ebd'::uuid, '73a19821-b4ed-5f4d-9555-ca88a3fbb640'::uuid, 'Quelle méthode convient le mieux pour devenir plus vite en sprint ?', 'mcq', '["Des sorties de deux heures à allure lente","Des sprints courts avec récupération complète","Des étirements de dix minutes","Un sprint chaque minute sans pause"]'::jsonb, 1, 'Pour rester vraiment vite, il faut repartir frais : sprints courts et récupération complète entre chaque.', 4),
    ('de33a82d-2137-557a-8b62-9e114989aa54'::uuid, '73a19821-b4ed-5f4d-9555-ca88a3fbb640'::uuid, 'Quel moteur est entraîné par de longues sorties à allure modérée ?', 'mcq', '["La force maximale","Le temps de réaction","L’endurance","La souplesse"]'::jsonb, 2, 'L’endurance aérobie se construit en tenant longtemps : des efforts longs et réguliers.', 5),
    ('282f53d7-7b95-5b0b-b918-12f42748548e'::uuid, '73a19821-b4ed-5f4d-9555-ca88a3fbb640'::uuid, 'Le test navette de Luc Léger, créé en 1982, évalue…', 'mcq', '["la détente verticale","la souplesse","l’endurance","la précision de tir"]'::jsonb, 2, 'On court en aller-retour sur 20 mètres au rythme de bips de plus en plus rapides : le test mesure l’endurance.', 6),
    ('415d13e1-e0ee-57c9-81e4-8c11121dc20a'::uuid, '73a19821-b4ed-5f4d-9555-ca88a3fbb640'::uuid, 'À 14 ans, il vaut mieux soulever la charge maximale pour progresser plus vite en force.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La force maximale attend la fin de la croissance : à cet âge, on travaille la technique et le poids du corps.', 7),
    ('e3de1c59-2c9e-5ebd-b1e5-29ecc3a37b9e'::uuid, '73a19821-b4ed-5f4d-9555-ca88a3fbb640'::uuid, 'Parmi ces trois composantes, laquelle ne fait PAS partie de la vitesse ?', 'mcq', '["La fréquence des mouvements","Le temps de réaction","L’amplitude de la foulée","La souplesse du tronc"]'::jsonb, 3, 'La vitesse regroupe réaction, fréquence et amplitude. La souplesse est une autre qualité.', 8),
    ('cd816d96-7059-5996-8af0-365de310dd06'::uuid, '73a19821-b4ed-5f4d-9555-ca88a3fbb640'::uuid, 'Que travaille le saut en longueur sans élan ?', 'mcq', '["La détente des jambes","L’endurance aérobie","La coordination des bras","La souplesse du dos"]'::jsonb, 0, 'Ce test mesure la puissance des jambes sur un seul effort, c’est-à-dire la détente.', 9),
    ('7f7ae998-3cdb-5726-bafa-da5ac7c4d1e1'::uuid, '73a19821-b4ed-5f4d-9555-ca88a3fbb640'::uuid, 'La coordination est la capacité de faire travailler ensemble ses membres et son regard.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Dribbler en courant ou réceptionner un ballon demande à tout le corps de travailler ensemble : c’est la coordination.', 10),
    ('68685cdc-4a30-5a3a-a3ab-20dd7d1769e0'::uuid, '73a19821-b4ed-5f4d-9555-ca88a3fbb640'::uuid, 'Pourquoi refaire un test physique trois mois plus tard ?', 'mcq', '["Parce que les résultats changent chaque jour","Pour remplacer l’échauffement","Pour battre les autres élèves","Pour se comparer à soi-même et vérifier ses progrès"]'::jsonb, 3, 'Le but d’un test est de mesurer sa propre progression : même test, mêmes conditions, quelques mois d’écart.', 11),
    ('8e73b7ac-9c45-5748-93d9-bab47c19adcf'::uuid, '73a19821-b4ed-5f4d-9555-ca88a3fbb640'::uuid, 'Quelles qualités un adolescent de 13 à 15 ans travaille-t-il particulièrement bien ?', 'mcq', '["La force maximale","Aucune : il est trop jeune","Uniquement la souplesse","La coordination et la vitesse"]'::jsonb, 3, 'Le cerveau apprend vite les gestes nouveaux à cet âge : coordination et vitesse progressent très bien.', 12),
    ('d4a9c41f-1b98-5d4f-82b3-4ba039a64b87'::uuid, '99acadda-8cec-5ca2-a133-5a203da78889'::uuid, 'Qu’est-ce que l’hypertrophie musculaire ?', 'mcq', '["L’épaississement des fibres qui composent le muscle","L’augmentation du nombre de muscles du corps","La fonte du muscle quand on arrête le sport","L’allongement des os pendant la croissance"]'::jsonb, 0, 'Un muscle grossit parce que chacune de ses fibres s’épaissit : leur nombre, lui, ne change presque pas.', 1),
    ('eb0198b2-b59f-575e-8b41-0e1b58e7cb8f'::uuid, '99acadda-8cec-5ca2-a133-5a203da78889'::uuid, 'Après une séance, pendant combien de temps le muscle fabrique-t-il des protéines pour se réparer ?', 'mcq', '["Environ 24 à 48 heures","Une dizaine de minutes","Une semaine entière","Seulement pendant la séance"]'::jsonb, 0, 'C’est pendant ces 24 à 48 heures de récupération que la fibre se reconstruit un peu plus épaisse : d’où le repos entre deux séances du même muscle.', 2),
    ('3c43026b-a257-567c-9075-650d792dccad'::uuid, '99acadda-8cec-5ca2-a133-5a203da78889'::uuid, 'Plus on a de courbatures, plus le muscle grossit.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La courbature signale des micro-lésions, pas le progrès : on progresse souvent sans courbature, et on peut avoir des courbatures sans progresser.', 3),
    ('62720fb0-c7d4-5eb4-9e16-e312072fc005'::uuid, '99acadda-8cec-5ca2-a133-5a203da78889'::uuid, 'Quelle fourchette de répétitions par série vise le mieux la prise de muscle ?', 'mcq', '["8 à 12","1 à 3","30 à 50","Au moins 100"]'::jsonb, 0, 'Entre 8 et 12 répétitions avec une charge qui fatigue à la fin de la série : assez lourd pour tendre le muscle, assez long pour le fatiguer.', 4),
    ('e87b96fa-d5b2-5ad7-8287-a1315fd5ed43'::uuid, '99acadda-8cec-5ca2-a133-5a203da78889'::uuid, 'Quel est le levier principal de l’hypertrophie ?', 'mcq', '["La tension mécanique : la force produite contre une résistance","La température du muscle","La vitesse à laquelle on court","Le nombre de muscles sollicités"]'::jsonb, 0, 'Sans tension mécanique, rien ne pousse la fibre à s’épaissir ; la brûlure et les micro-lésions ne font que l’accompagner.', 5),
    ('1af03ff7-d688-5aef-9258-cf9dbafd430c'::uuid, '99acadda-8cec-5ca2-a133-5a203da78889'::uuid, 'Entraîner le même muscle tous les jours le fait grossir plus vite.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Sans 48 heures de repos, le muscle n’a pas le temps de se reconstruire : on casse un mur qu’on n’a pas fini de remonter.', 6),
    ('0af27321-f840-59b8-a430-c096e420c77d'::uuid, '99acadda-8cec-5ca2-a133-5a203da78889'::uuid, 'À 14 ans, quelle est la priorité en musculation ?', 'mcq', '["Apprendre le geste juste avant d’ajouter de la charge","Soulever le plus lourd possible","S’entraîner chaque jour sans exception","Prendre des protéines en poudre"]'::jsonb, 0, 'Le squelette finit de grandir et ses cartilages de croissance sont fragiles : technique, poids du corps et charges légères, jamais de charge maximale.', 7),
    ('3d9605c2-da62-5706-8b69-c1f5fb11df0f'::uuid, '99acadda-8cec-5ca2-a133-5a203da78889'::uuid, 'Au début d’un entraînement de force, les progrès rapides viennent surtout…', 'mcq', '["du système nerveux, qui apprend à recruter plus de fibres en même temps","de muscles qui ont déjà grossi","d’une alimentation plus riche","de la chance"]'::jsonb, 0, 'Les premières semaines, le cerveau commande mieux les fibres existantes : la force monte avant que le muscle ne grossisse.', 8),
    ('38ce2b8e-17fd-5e6b-8420-06f12f37f0c0'::uuid, '99acadda-8cec-5ca2-a133-5a203da78889'::uuid, 'De quoi un muscle a-t-il besoin pour se reconstruire après l’effort ?', 'mcq', '["De protéines, de sommeil et de repos","De sucre uniquement","De courbatures","D’anabolisants"]'::jsonb, 0, 'Les protéines apportent les briques, le sommeil et le repos donnent le temps : les trois ensemble, sinon rien ne se construit.', 9),
    ('9dcb3947-f4bd-5e36-85b1-20d8ab71e7ce'::uuid, '99acadda-8cec-5ca2-a133-5a203da78889'::uuid, 'Les anabolisants sont interdits et dangereux pour le cœur et les hormones.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Ce sont des hormones de synthèse : interdites par la loi et par l’antidopage, elles abîment le cœur, le foie et le système hormonal, et bloquent la croissance.', 10),
    ('9073ccff-d293-5e0c-b4ed-0620e20bb4e4'::uuid, '99acadda-8cec-5ca2-a133-5a203da78889'::uuid, 'Qu’appelle-t-on la surcompensation ?', 'mcq', '["La fibre se reconstruit un peu plus épaisse qu’avant l’effort","Un excès d’entraînement qui épuise","Une crampe qui dure plusieurs jours","Le gonflement du muscle pendant la séance"]'::jsonb, 0, 'Après la réparation, le muscle reconstruit « par anticipation », un peu au-dessus de son niveau de départ : c’est ce surplus qui fait progresser.', 11),
    ('57212c27-d6f4-5176-8017-87f9c1f28662'::uuid, '99acadda-8cec-5ca2-a133-5a203da78889'::uuid, 'Le muscle gonflé juste après une séance (la congestion), c’est…', 'mcq', '["temporaire : du sang et de l’eau, pas du muscle en plus","définitif : le muscle vient de grossir","dangereux : il faut arrêter","le signe d’une blessure"]'::jsonb, 0, 'Pendant l’effort, le sang afflue : le muscle paraît plus gros pendant une heure, puis revient à sa taille. Le vrai gain vient des jours suivants.', 12),
    ('d859ec3b-81ee-5506-ba57-e9be45ab0a36'::uuid, '031d651e-51ad-5c5e-aba7-793e1e409a3f'::uuid, 'Que mesure la VO2max ?', 'mcq', '["La vitesse maximale en sprint","Le nombre de battements du cœur au repos","La quantité maximale d’oxygène que le corps peut utiliser par minute","La force maximale des jambes"]'::jsonb, 2, 'La VO2max est la quantité maximale d’oxygène utilisée par minute, exprimée en ml/min/kg.', 1),
    ('c2439cfc-2f6d-565e-ad10-8c4ff7d936d6'::uuid, '031d651e-51ad-5c5e-aba7-793e1e409a3f'::uuid, 'Que signifie le sigle VMA ?', 'mcq', '["Vitesse maximale aérobie","Volume musculaire accéléré","Variation maximale d’allure","Vitesse moyenne annuelle"]'::jsonb, 0, 'La VMA est la vitesse de course à laquelle on atteint sa VO2max, exprimée en km/h.', 2),
    ('f79e3d40-ab7b-5155-a9d0-285fa6eda99f'::uuid, '031d651e-51ad-5c5e-aba7-793e1e409a3f'::uuid, 'Une VMA de 12 km/h correspond à un kilomètre en…', 'mcq', '["5 minutes","4 minutes","6 minutes","7 minutes"]'::jsonb, 0, 'On divise 60 minutes par 12 km/h : 60 ÷ 12 = 5 minutes par kilomètre.', 3),
    ('09cfa60f-85f4-5cc6-9c10-c33aef47518c'::uuid, '031d651e-51ad-5c5e-aba7-793e1e409a3f'::uuid, 'Quelle valeur de VO2max est typique d’un adolescent en bonne santé ?', 'mcq', '["Environ 80 à 90 ml/min/kg","Environ 150 ml/min/kg","Environ 5 à 10 ml/min/kg","Environ 40 à 50 ml/min/kg"]'::jsonb, 3, 'Un adolescent en bonne santé tourne autour de 40 à 50 ; les meilleurs coureurs et cyclistes atteignent 80 à 90.', 4),
    ('51c8dedb-568e-57a4-8068-3f76fb67bc66'::uuid, '031d651e-51ad-5c5e-aba7-793e1e409a3f'::uuid, 'L’endurance fondamentale se travaille à environ…', 'mcq', '["150 % de la VMA","60 à 70 % de la VMA","100 à 110 % de la VMA","30 % de la VMA"]'::jsonb, 1, 'L’endurance fondamentale est une allure confortable, entre 60 et 70 % de la VMA, où l’on peut encore parler.', 5),
    ('e217a0df-e067-5c45-8a90-fcf433341890'::uuid, '031d651e-51ad-5c5e-aba7-793e1e409a3f'::uuid, 'Avec une VMA de 12 km/h, à quelle vitesse court-on un fractionné à 100 % de VMA ?', 'mcq', '["8 km/h","6 km/h","12 km/h","20 km/h"]'::jsonb, 2, '100 % de 12 km/h, c’est 12 km/h : l’allure du fractionné part de la VMA elle-même.', 6),
    ('0bcc8ca0-fd5f-57b3-8899-a1a1bb6b40b1'::uuid, '031d651e-51ad-5c5e-aba7-793e1e409a3f'::uuid, 'Pour progresser en endurance, la meilleure recette est surtout…', 'mcq', '["Du fractionné tous les jours","Ne jamais courir lentement","Beaucoup de volume lent et un peu de fractionné","Uniquement des sprints de 10 secondes"]'::jsonb, 2, 'Le volume lent bâtit la base sans fatiguer ; un peu de fractionné fait monter la VMA.', 7),
    ('b7edf957-f809-516d-868f-dff6299fee51'::uuid, '031d651e-51ad-5c5e-aba7-793e1e409a3f'::uuid, 'Kelvin Kiptum a établi le record du monde du marathon à Chicago en 2023.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le 8 octobre 2023, il a couru en 2 h 00 min 35 s, record officiel du marathon masculin.', 8),
    ('7f2f3b1b-eb7b-5cfc-91b1-fdbd19d7774c'::uuid, '031d651e-51ad-5c5e-aba7-793e1e409a3f'::uuid, 'La course d’Eliud Kipchoge sous les 2 heures à Vienne en 2019 est un record du monde officiel.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle était hors des règles des compétitions (meneurs relayés, équipement spécial) : elle ne compte pas comme record officiel.', 9),
    ('84381fb6-7ac2-57bd-8a26-e03bfe63d64f'::uuid, '031d651e-51ad-5c5e-aba7-793e1e409a3f'::uuid, 'Comment passe-t-on d’une vitesse en km/h à un temps au kilomètre ?', 'mcq', '["On ajoute 60 à la vitesse","On divise 60 par la vitesse","On multiplie la vitesse par 60","On soustrait 60 à la vitesse"]'::jsonb, 1, 'Un kilomètre à 10 km/h dure 60 ÷ 10 = 6 minutes : la division fait passer de la vitesse au temps.', 10),
    ('73c83160-1b10-5f6f-ae63-b436ea6450ed'::uuid, '031d651e-51ad-5c5e-aba7-793e1e409a3f'::uuid, 'Courir plus vite à l’endurance fondamentale bâtit mieux la base.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Trop vite, on s’épuise sans bâtir la base : l’endurance fondamentale doit rester une allure où l’on peut parler.', 11),
    ('f63c878a-7d06-5c39-a6ec-ec2af9b8ea97'::uuid, '031d651e-51ad-5c5e-aba7-793e1e409a3f'::uuid, 'Quel test de terrain permet d’estimer sa VMA ?', 'mcq', '["La flexion du tronc","La navette de 20 mètres de Luc Léger","Le saut en longueur sans élan","Le lancer de poids"]'::jsonb, 1, 'On accélère par paliers au rythme de bips jusqu’à ne plus pouvoir suivre : le dernier palier tenu donne la VMA.', 12),
    ('d3a616cc-d79e-53ea-8130-234f6c9ebe7f'::uuid, '987e7820-009f-51e3-8080-dbec42b52f0b'::uuid, 'Dans le cycle de l’entraînement, que désigne la surcompensation ?', 'mcq', '["La fatigue juste après l’effort","Le corps reconstruit un peu au-dessus de son niveau de départ","Un excès d’entraînement","Une douleur musculaire"]'::jsonb, 1, 'Après la réparation, le corps reconstruit un peu plus fort qu’avant : c’est cette marche gagnée qui fait progresser.', 1),
    ('e215d905-2fad-5c22-b80d-76f3f7d72794'::uuid, '987e7820-009f-51e3-8080-dbec42b52f0b'::uuid, 'Combien d’heures de sommeil conseille-t-on entre 14 et 17 ans ?', 'mcq', '["4 à 5 heures","12 à 14 heures","8 à 10 heures","6 heures exactement"]'::jsonb, 2, 'À cet âge, le corps grandit et se répare beaucoup : 8 à 10 heures par nuit.', 2),
    ('8808c802-93e7-542d-974d-bfc2cdb94c19'::uuid, '987e7820-009f-51e3-8080-dbec42b52f0b'::uuid, 'Quelle hormone est sécrétée pendant le sommeil profond et aide à réparer les muscles ?', 'mcq', '["L’insuline","L’hormone de croissance","La mélatonine","L’adrénaline"]'::jsonb, 1, 'L’hormone de croissance est sécrétée surtout pendant le sommeil profond : le sommeil fait partie de l’entraînement.', 3),
    ('ff040322-cb79-5603-896b-18789754145d'::uuid, '987e7820-009f-51e3-8080-dbec42b52f0b'::uuid, 'Pourquoi les écrans retardent-ils l’endormissement ?', 'mcq', '["Ils font monter la température du corps","Leur lumière bloque la mélatonine, l’hormone du sommeil","Ils produisent des protéines","Ils fatiguent les muscles"]'::jsonb, 1, 'La lumière des écrans empêche la sécrétion de mélatonine, qui donne le signal de dormir.', 4),
    ('ededcbe0-8364-55f2-bab0-5542eb732f21'::uuid, '987e7820-009f-51e3-8080-dbec42b52f0b'::uuid, 'Après l’effort, dans quel délai est-il conseillé de manger glucides et protéines ?', 'mcq', '["Au bout de six heures","Seulement le lendemain","Dans les deux heures","Jamais : il vaut mieux jeûner"]'::jsonb, 2, 'Dans les deux heures, les glucides refont les réserves et les protéines aident à réparer.', 5),
    ('8a71fbe3-7c9a-5829-a1ec-1a02bee2ac0f'::uuid, '987e7820-009f-51e3-8080-dbec42b52f0b'::uuid, 'Un jour de repos est un jour perdu pour la progression.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le repos est le moment où la surcompensation se construit : il fait partie du programme.', 6),
    ('17e5f752-c52e-5455-9d87-9b251a0b2da0'::uuid, '987e7820-009f-51e3-8080-dbec42b52f0b'::uuid, 'Que fait-on pour la récupération active ?', 'mcq', '["On bouge doucement : marche ou vélo tranquille","On reste couché toute la journée","On refait une séance intense","On saute le repas"]'::jsonb, 0, 'Bouger doucement aide à se sentir mieux sans réentraîner les muscles fatigués.', 7),
    ('eeaeafe7-9b76-568f-b6f1-f9dd8aa9afff'::uuid, '987e7820-009f-51e3-8080-dbec42b52f0b'::uuid, 'Lequel de ces signes peut indiquer un surentraînement ?', 'mcq', '["Une envie de courir plus longtemps","Un appétit stable","Une fréquence cardiaque de repos qui monte","Des courbatures légères après un effort"]'::jsonb, 2, 'Fatigue persistante, cœur qui s’emballe au repos, sommeil cassé et performances en baisse sont des signaux d’alerte.', 8),
    ('907a66da-1ac0-52e7-90e8-4a27e8ac93a3'::uuid, '987e7820-009f-51e3-8080-dbec42b52f0b'::uuid, 'Face à un surentraînement, la bonne réponse est de s’entraîner davantage.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il faut récupérer, pas en faire plus : le corps a besoin de temps pour se reconstruire.', 9),
    ('eac66269-7aab-55c1-ba8a-62071f022622'::uuid, '987e7820-009f-51e3-8080-dbec42b52f0b'::uuid, 'Que sait-on des étirements contre les courbatures ?', 'mcq', '["Ils sont agréables, mais leur effet n’est pas prouvé","Ils les aggravent toujours","Ils remplacent le sommeil","Ils les suppriment toujours"]'::jsonb, 0, 'Les étirements font du bien, mais aucune preuve solide ne montre qu’ils évitent les courbatures.', 10),
    ('db712c9e-892a-52a3-8a2c-4b0cdc51718f'::uuid, '987e7820-009f-51e3-8080-dbec42b52f0b'::uuid, 'S’entraîner avant la fin de la réparation permet de progresser plus vite.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Réentraîner un corps pas encore réparé, c’est partir d’un niveau plus bas : rien n’est gagné.', 11),
    ('622c1537-1eae-50c0-a243-af8884ee4c83'::uuid, '987e7820-009f-51e3-8080-dbec42b52f0b'::uuid, 'Quel effet ont le froid et le massage sur la récupération ?', 'mcq', '["Un effet dangereux","Un effet immédiat et total","Aucun effet sur le bien-être","Un effet modeste"]'::jsonb, 3, 'Ils font du bien sans remplacer le sommeil, le repos et l’assiette.', 12),
    ('7d9ec16a-fdd2-5831-b339-e80b97335154'::uuid, '61b55e00-4931-5522-a825-a67eff651b72'::uuid, 'Combien de temps dure un échauffement efficace ?', 'mcq', '["Une heure","30 secondes","Aucun temps : on s’échauffe en jouant","10 à 15 minutes"]'::jsonb, 3, 'Dix à quinze minutes suffisent à préparer cœur, articulations et gestes du sport.', 1),
    ('e187c8f5-990d-57a4-9e37-0f008290f9ba'::uuid, '61b55e00-4931-5522-a825-a67eff651b72'::uuid, 'Dans quel ordre se déroule un bon échauffement ?', 'mcq', '["Gestes à vitesse maximale, puis cardio","Cardio léger, mobilité, puis gestes spécifiques accélérés","Étirements longs, puis sprint, puis repos","Aucun ordre particulier"]'::jsonb, 1, 'On monte progressivement : d’abord le cœur et les articulations, ensuite les gestes du sport de plus en plus vite.', 2),
    ('4f494d01-a90f-517f-a7f1-573298cb62cd'::uuid, '61b55e00-4931-5522-a825-a67eff651b72'::uuid, 'Que réduit environ d’un tiers le programme FIFA 11+ chez les jeunes footballeurs ?', 'mcq', '["Le temps de jeu","Le nombre de buts","Les blessures","Les fautes sifflées"]'::jsonb, 2, 'Pratiqué régulièrement, ce programme d’échauffement diminue les blessures d’environ un tiers.', 3),
    ('81b5a759-0543-55f4-a6ec-12945d8cba08'::uuid, '61b55e00-4931-5522-a825-a67eff651b72'::uuid, 'Quel type d’étirement fait-on plutôt avant l’effort ?', 'mcq', '["Aucun étirement jamais","Statique, tenu une minute","Dynamique, en mouvement","Forcé jusqu’à la douleur"]'::jsonb, 2, 'Les mouvements amples préparent les articulations sans diminuer la force.', 4),
    ('54ebb3f0-f600-5745-8658-e4335e6cd0ca'::uuid, '61b55e00-4931-5522-a825-a67eff651b72'::uuid, 'Les étirements statiques longs avant l’effort préviennent les blessures.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Avant l’effort, ils diminuent la force un moment et ne préviennent pas les blessures : on les garde pour après.', 5),
    ('8c417415-1503-5d0f-96d3-852e96bed31a'::uuid, '61b55e00-4931-5522-a825-a67eff651b72'::uuid, 'À quoi sert surtout le gainage ?', 'mcq', '["À prendre du poids","À gagner en souplesse","À courir plus vite","À protéger le dos"]'::jsonb, 3, 'Planche et gainage latéral renforcent les muscles profonds qui soutiennent la colonne.', 6),
    ('de863bae-7589-5af2-a0ec-d819947b4ecd'::uuid, '61b55e00-4931-5522-a825-a67eff651b72'::uuid, 'Quel exercice travaille la proprioception de la cheville ?', 'mcq', '["Soulever une charge lourde","S’étirer les bras","Tenir en équilibre sur un pied","Courir en ligne droite"]'::jsonb, 2, 'Tenir sur un pied, yeux ouverts puis fermés, entraîne la cheville à corriger les déséquilibres.', 7),
    ('0409b27f-8be2-572d-b2fd-604c4a6941eb'::uuid, '61b55e00-4931-5522-a825-a67eff651b72'::uuid, 'De combien peut-on augmenter la charge d’entraînement d’une semaine à l’autre, selon la règle courante ?', 'mcq', '["Autant qu’on veut","De 100 %","Pas plus de 10 %","De 50 %"]'::jsonb, 2, 'La progressivité protège les tendons et les os : pas plus de 10 % en plus d’une semaine à l’autre.', 8),
    ('71f7df27-1cbc-5e85-8972-b37105728593'::uuid, '61b55e00-4931-5522-a825-a67eff651b72'::uuid, 'La maladie d’Osgood-Schlatter touche surtout…', 'mcq', '["l’épaule des nageurs adultes","le genou, entre 10 et 15 ans","le poignet, après 60 ans","le dos des enfants de 3 ans"]'::jsonb, 1, 'C’est une douleur de croissance sous le genou, fréquente entre 10 et 15 ans.', 9),
    ('46a57bb6-e6a4-5caf-a38b-24b92ad5fdab'::uuid, '61b55e00-4931-5522-a825-a67eff651b72'::uuid, 'Que fait-on devant une douleur de croissance comme celle de Sever au talon ?', 'mcq', '["On l’ignore","On supprime tout le sport pour toujours","On adapte l’activité sans forcer","On double l’entraînement"]'::jsonb, 2, 'Moins de sauts, moins de sol dur : on adapte, et la douleur passe avec le temps.', 10),
    ('eeb6c5c0-017e-5ccb-97f0-088959f63da2'::uuid, '61b55e00-4931-5522-a825-a67eff651b72'::uuid, 'Une douleur qui dure plusieurs jours doit être ignorée pour continuer à progresser.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Une douleur qui dure ou qui augmente mérite l’avis d’un médecin : on n’avance pas malgré la douleur.', 11),
    ('2767b756-1c5f-5c25-87c3-d0b93a3ebc01'::uuid, '61b55e00-4931-5522-a825-a67eff651b72'::uuid, 'Qu’est-ce que la proprioception ?', 'mcq', '["Savoir où sont ses articulations sans les regarder","La capacité à courir longtemps","La souplesse du dos","La puissance d’un sprint"]'::jsonb, 0, 'C’est le sens de la position du corps, qui permet à la cheville de corriger un faux pas avant la torsion.', 12),
    ('3e4bc151-d985-5a7b-9902-684805b9a44f'::uuid, 'd2960418-0e1c-50a5-b124-0c7c5753ae81'::uuid, 'Où et quand le CIO est-il créé ?', 'mcq', '["À la Sorbonne, à Paris, le 23 juin 1894","À Athènes, en 1896","À Londres, en 1908","À Berlin, en 1936"]'::jsonb, 0, 'Le congrès de la Sorbonne crée le CIO le 23 juin 1894 ; les premiers Jeux ont lieu deux ans plus tard à Athènes.', 1),
    ('cb28cd47-5bdd-5182-a22b-4b8976d6e805'::uuid, 'd2960418-0e1c-50a5-b124-0c7c5753ae81'::uuid, 'Quelle ville accueille les premiers Jeux olympiques modernes en 1896 ?', 'mcq', '["New York","Rome","Athènes","Paris"]'::jsonb, 2, 'Les premiers Jeux modernes se tiennent à Athènes en 1896, en hommage à la Grèce antique.', 2),
    ('68fa94c0-21e3-54c2-91ba-8c592a62276b'::uuid, 'd2960418-0e1c-50a5-b124-0c7c5753ae81'::uuid, 'Qui est à l’origine de la devise « Citius, Altius, Fortius » ?', 'mcq', '["Le dominicain Henri Didon","Alice Milliat","Jules Rimet","Pierre de Coubertin seul"]'::jsonb, 0, 'Henri Didon la lance en 1891 ; Coubertin l’adopte ensuite pour les Jeux.', 3),
    ('f589f3cf-f88e-5c43-a661-f90416821538'::uuid, 'd2960418-0e1c-50a5-b124-0c7c5753ae81'::uuid, 'Que veut dire « Citius, Altius, Fortius » ?', 'mcq', '["Plus vite, plus haut, plus fort","Plus tôt, plus tard, plus loin","Ensemble, unis, solidaires","Gagner, jouer, participer"]'::jsonb, 0, 'C’est la devise latine des Jeux : plus vite, plus haut, plus fort.', 4),
    ('f44df6e5-5e73-5a9a-a062-dd34f1643c0d'::uuid, 'd2960418-0e1c-50a5-b124-0c7c5753ae81'::uuid, 'Quel est le plus vieux club sportif français cité par l’histoire du sport ?', 'mcq', '["Le Havre Athletic Club, créé en 1872","L’Olympique de Marseille, créé en 1899","Le Paris Saint-Germain, créé en 1970","Le Stade de France, créé en 1998"]'::jsonb, 0, 'Le Havre Athletic Club, fondé en 1872, est considéré comme le plus vieux club français.', 5),
    ('654e0339-22b2-5644-8f8d-c144930b725f'::uuid, 'd2960418-0e1c-50a5-b124-0c7c5753ae81'::uuid, 'Coubertin était favorable à la compétition sportive féminine.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il était opposé au sport féminin de compétition : c’est l’une de ses limites, que les femmes ont dû combattre.', 6),
    ('e6f9e627-eb25-5355-9fd9-9770b9a76ce3'::uuid, 'd2960418-0e1c-50a5-b124-0c7c5753ae81'::uuid, 'Que crée Alice Milliat à Paris en 1922 ?', 'mcq', '["Le CIO","Les Jeux mondiaux féminins","La Coupe du monde de football","Le Tour de France"]'::jsonb, 1, 'Alice Milliat organise les premiers Jeux mondiaux féminins pour que les femmes puissent concourir.', 7),
    ('a04b9db1-3b79-5e75-8888-c411271c7d45'::uuid, 'd2960418-0e1c-50a5-b124-0c7c5753ae81'::uuid, 'Qui est à l’origine de la Coupe du monde de football, jouée pour la première fois en 1930 ?', 'mcq', '["Jules Rimet, président de la FIFA","Pierre de Coubertin","Thomas Arnold","Henri Didon"]'::jsonb, 0, 'Jules Rimet, président de la FIFA, imagine le tournoi mondial, joué en Uruguay en 1930.', 8),
    ('1a96bb8c-488f-53e3-9fbe-7ace859b8278'::uuid, 'd2960418-0e1c-50a5-b124-0c7c5753ae81'::uuid, 'Le modèle d’éducation par le sport que Coubertin admire vient…', 'mcq', '["Des écoles de Sparte antique","D’une académie japonaise","D’une université américaine","Des écoles anglaises comme Rugby School"]'::jsonb, 3, 'Coubertin admire l’école anglaise, où Thomas Arnold fait du sport un moyen de former le caractère.', 9),
    ('6567e674-e125-5fb4-9d55-fc640eb64e27'::uuid, 'd2960418-0e1c-50a5-b124-0c7c5753ae81'::uuid, 'La phrase « L’important n’est pas le triomphe mais le combat » est une invention de Coubertin sans autre origine.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Coubertin la cite en 1908 en reprenant un propos de l’évêque Ethelbert Talbot.', 10),
    ('97609103-6983-584b-8598-2952ec958357'::uuid, 'd2960418-0e1c-50a5-b124-0c7c5753ae81'::uuid, 'Que fait l’USFSA, créée en 1887 ?', 'mcq', '["Elle gère la Coupe du monde","Elle organise les Jeux olympiques","Elle fabrique du matériel sportif","Elle fédère des sociétés sportives françaises"]'::jsonb, 3, 'L’USFSA rassemble les sociétés sportives françaises : un pas vers le sport organisé.', 11),
    ('393a3475-f3ae-5456-8ce5-dd120adae406'::uuid, 'd2960418-0e1c-50a5-b124-0c7c5753ae81'::uuid, 'Les premiers Jeux mondiaux féminins ont eu lieu à Paris.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Alice Milliat les a organisés à Paris en 1922, avec des athlètes de plusieurs pays.', 12),
    ('a0142361-5a47-5e44-9975-9a014e92c9e4'::uuid, '4596f8f1-ff3c-5157-9d8e-62fa644b6b0f'::uuid, 'En quelle année le Tour de France est-il créé ?', 'mcq', '["1952","1919","1903","1985"]'::jsonb, 2, 'Le journal L’Auto lance la première édition en 1903, avec 6 étapes et 2 428 km.', 1),
    ('caf29442-afc4-5c74-b3e3-3b1d1baeecf8'::uuid, '4596f8f1-ff3c-5157-9d8e-62fa644b6b0f'::uuid, 'Pourquoi le journal L’Auto a-t-il créé le Tour de France ?', 'mcq', '["Pour fêter une victoire militaire","Pour promouvoir un fabricant de vélos","Pour vendre davantage de journaux","Pour former des champions olympiques"]'::jsonb, 2, 'Desgrange et L’Auto cherchaient à augmenter leurs ventes : la course était d’abord une opération de presse.', 2),
    ('8b49fea4-3ea4-56d7-a7e9-d1860793e998'::uuid, '4596f8f1-ff3c-5157-9d8e-62fa644b6b0f'::uuid, 'Qui a gagné la toute première édition du Tour ?', 'mcq', '["Maurice Garin","Bernard Hinault","Miguel Indurain","Eddy Merckx"]'::jsonb, 0, 'Maurice Garin remporte le Tour de 1903, sur 6 étapes et 2 428 km.', 3),
    ('2eee353f-600c-5fd4-a7c3-6d69f255d0aa'::uuid, '4596f8f1-ff3c-5157-9d8e-62fa644b6b0f'::uuid, 'Pourquoi le maillot du leader est-il jaune ?', 'mcq', '["Parce que le soleil brille en juillet","Parce que le jaune se voit de loin","Parce que c’est la couleur de la France","Parce que le journal L’Auto était imprimé sur du papier jaune"]'::jsonb, 3, 'La couleur reprend celle du papier du journal organisateur ; le maillot jaune apparaît en 1919.', 4),
    ('11b413b2-7626-5c97-9664-1dd620742662'::uuid, '4596f8f1-ff3c-5157-9d8e-62fa644b6b0f'::uuid, 'Quel maillot récompense le meilleur grimpeur ?', 'mcq', '["Le maillot blanc","Le maillot à pois","Le maillot vert","Le maillot jaune"]'::jsonb, 1, 'Le maillot à pois est celui du meilleur grimpeur ; le vert va au sprinteur et le blanc au meilleur jeune.', 5),
    ('03551461-7879-5127-be12-560eda7833d0'::uuid, '4596f8f1-ff3c-5157-9d8e-62fa644b6b0f'::uuid, 'Quel est le dernier Français vainqueur du Tour de France ?', 'mcq', '["Laurent Fignon, en 2000","Jacques Anquetil, en 1964","Bernard Hinault, en 1985","Richard Virenque, en 1999"]'::jsonb, 2, 'Bernard Hinault l’a emporté en 1985 : depuis, aucun Français n’a gagné.', 6),
    ('fc200a9c-2408-5e6e-ba3f-19967949a31b'::uuid, '4596f8f1-ff3c-5157-9d8e-62fa644b6b0f'::uuid, 'Que s’est-il passé pour Lance Armstrong en 2012 ?', 'mcq', '["Il a pris sa retraite sportive","Il a été élu président de l’UCI","Il a été déchu de ses sept Tours pour dopage","Il a gagné un huitième Tour"]'::jsonb, 2, 'Reconnu coupable de dopage, il a perdu ses sept victoires.', 7),
    ('ea6ba4ac-b95a-55a1-8669-d2b45607d007'::uuid, '4596f8f1-ff3c-5157-9d8e-62fa644b6b0f'::uuid, 'Combien d’étapes compte le Tour de France actuel ?', 'mcq', '["21","3","60","6"]'::jsonb, 0, 'Le Tour actuel compte 21 étapes en juillet, pour environ 3 400 km.', 8),
    ('2af6a8c3-9629-53a0-9501-bb1aadd3bfb0'::uuid, '4596f8f1-ff3c-5157-9d8e-62fa644b6b0f'::uuid, 'Le Tour de France Femmes existe depuis 2022.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Il a été lancé en 2022 ; Pauline Ferrand-Prévot l’a gagné en 2025.', 9),
    ('a11958d1-6cd6-5f5b-b533-ff1e2e9a0f25'::uuid, '4596f8f1-ff3c-5157-9d8e-62fa644b6b0f'::uuid, 'Le Tour de France est né pour un but sportif sans lien avec l’argent.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est une idée de journal pour vendre du papier : la presse est à l’origine de la course.', 10),
    ('8f78811b-c67e-5f9b-9def-2c2d9bc345a0'::uuid, '4596f8f1-ff3c-5157-9d8e-62fa644b6b0f'::uuid, 'Qui a remporté le Tour de France en 2024 et 2025 ?', 'mcq', '["Eddy Merckx","Tadej Pogačar","Miguel Indurain","Bernard Hinault"]'::jsonb, 1, 'Pogačar l’a emporté en 2020, 2021, 2024 et 2025.', 11),
    ('33ca3016-3b35-5cb1-9bb9-580b1d61b614'::uuid, '4596f8f1-ff3c-5157-9d8e-62fa644b6b0f'::uuid, 'Que crie Octave Lapize aux organisateurs au Tourmalet en 1910 ?', 'mcq', '["« Encore un tour ! »","« Vous êtes des assassins ! »","« Vive la France ! »","« Je suis le meilleur ! »"]'::jsonb, 1, 'Épuisé par l’ascension, il dénonce la dureté de l’étape : la montagne devient un mythe du Tour.', 12),
    ('00be9b21-f130-5d48-a220-b74a6c9a53cb'::uuid, 'a55a6c4a-1e48-5270-af66-83f85273b582'::uuid, 'Quel est le score de la finale de la Coupe du monde 1998 ?', 'mcq', '["France 3 – Brésil 0","France 2 – Brésil 1","France 4 – Brésil 2","France 1 – Brésil 0"]'::jsonb, 0, 'La France bat le Brésil 3-0 au Stade de France, le 12 juillet 1998.', 1),
    ('54e97aac-6126-5021-993e-c2256bfa8243'::uuid, 'a55a6c4a-1e48-5270-af66-83f85273b582'::uuid, 'Qui marque deux buts de la tête lors de la finale 1998 ?', 'mcq', '["Michel Platini","Didier Deschamps","Kylian Mbappé","Zinédine Zidane"]'::jsonb, 3, 'Zidane marque deux fois de la tête, avant le but de Petit.', 2),
    ('9593d985-619f-50a0-ba3b-4806a41dd9b8'::uuid, 'a55a6c4a-1e48-5270-af66-83f85273b582'::uuid, 'Qui est le sélectionneur de l’équipe de France championne du monde en 1998 ?', 'mcq', '["Aimé Jacquet","Michel Hidalgo","Raymond Domenech","Didier Deschamps"]'::jsonb, 0, 'Aimé Jacquet dirige les Bleus de 1998 ; Deschamps en sera le capitaine puis, plus tard, le sélectionneur.', 3),
    ('81587da4-b527-5817-814d-d8d8c5ec3d30'::uuid, 'a55a6c4a-1e48-5270-af66-83f85273b582'::uuid, 'Combien de buts Michel Platini a-t-il marqués à l’Euro 1984 ?', 'mcq', '["3","12","5","9"]'::jsonb, 3, 'Il marque 9 buts pendant le tournoi, un record, et la France gagne à domicile.', 4),
    ('3d3721e8-26d6-5355-93b4-06bf0002a6a1'::uuid, 'a55a6c4a-1e48-5270-af66-83f85273b582'::uuid, 'Contre quelle équipe la France gagne-t-elle la finale de la Coupe du monde 2018 ?', 'mcq', '["L’Argentine","Le Brésil","L’Italie","La Croatie"]'::jsonb, 3, 'La France bat la Croatie 4-2 à Moscou, le 15 juillet 2018.', 5),
    ('3da8b131-1b82-597f-bac7-110ae73ce040'::uuid, 'a55a6c4a-1e48-5270-af66-83f85273b582'::uuid, 'Quelle est la particularité de Didier Deschamps ?', 'mcq', '["Champion du monde comme joueur en 1998 et comme sélectionneur en 2018","Meilleur buteur de l’Euro 1984","Auteur d’un triplé en finale 2022","Fondateur du centre de Clairefontaine"]'::jsonb, 0, 'Il a soulevé la Coupe du monde deux fois, d’abord sur le terrain, ensuite sur le banc.', 6),
    ('9046574b-0070-56dd-9a88-43845f93f55c'::uuid, 'a55a6c4a-1e48-5270-af66-83f85273b582'::uuid, 'La finale de la Coupe du monde 2006 a été perdue par la France aux tirs au but.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Elle est restée célèbre aussi pour le coup de tête de Zidane, qui a été expulsé.', 7),
    ('5895dfa5-98e7-5d67-a9ba-e97d3774392d'::uuid, 'a55a6c4a-1e48-5270-af66-83f85273b582'::uuid, 'Quel joueur marque un triplé en finale de la Coupe du monde 2022 ?', 'mcq', '["Zinédine Zidane","Olivier Giroud","Antoine Griezmann","Kylian Mbappé"]'::jsonb, 3, 'Mbappé marque trois buts (3-3), mais l’Argentine gagne aux tirs au but.', 8),
    ('317c50f5-08f7-5e5c-8e90-9df732b8aa4d'::uuid, 'a55a6c4a-1e48-5270-af66-83f85273b582'::uuid, 'Que représente le centre de Clairefontaine, ouvert en 1988 ?', 'mcq', '["Le siège du CIO","Une école d’arbitrage","La formation des meilleurs jeunes footballeurs français","Un stade de 80 000 places"]'::jsonb, 2, 'Clairefontaine est le centre national de formation du football français.', 9),
    ('13a2e3ff-2890-52be-83f4-73b00144758f'::uuid, 'a55a6c4a-1e48-5270-af66-83f85273b582'::uuid, 'En 2025, le PSG est devenu le premier club français champion d’Europe depuis l’OM en 1993.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le PSG a battu l’Inter 5-0 à Munich, le 31 mai 2025.', 10),
    ('7273a110-7890-523b-ac23-030e368e6e59'::uuid, 'a55a6c4a-1e48-5270-af66-83f85273b582'::uuid, 'La France a remporté la Coupe du monde 2022 en battant l’Argentine.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La finale s’est terminée 3-3, puis l’Argentine l’a emporté aux tirs au but.', 11),
    ('6d55e660-7fc6-5238-b5c0-153ee9f539c8'::uuid, 'a55a6c4a-1e48-5270-af66-83f85273b582'::uuid, 'Quel résultat l’équipe de France féminine a-t-elle obtenu à l’Euro 2022 ?', 'mcq', '["Une médaille d’or","Une élimination au premier tour","Une victoire en finale","Une demi-finale"]'::jsonb, 3, 'Les Bleues ont atteint les demi-finales de l’Euro 2022.', 12),
    ('e465b149-c4b4-5eae-93fb-d547b2dbda0d'::uuid, '622fbe2a-98bf-52d5-bfc6-59cf04046940'::uuid, 'Pendant quelle manifestation se tiennent les Jeux de Paris en 1900 ?', 'mcq', '["La Coupe du monde de football","L’Exposition universelle","Un congrès du CIO","Le Tour de France"]'::jsonb, 1, 'Les Jeux de 1900 sont noyés dans l’Exposition universelle et durent cinq mois.', 1),
    ('9e5edddb-917b-5555-99db-fb836e395e5a'::uuid, '622fbe2a-98bf-52d5-bfc6-59cf04046940'::uuid, 'Qui est la première championne olympique de l’histoire, en 1900 ?', 'mcq', '["Marie-José Pérec, en athlétisme","Alice Milliat, en athlétisme","Charlotte Cooper, au tennis","Laure Manaudou, en natation"]'::jsonb, 2, 'Charlotte Cooper gagne le tournoi de tennis en 1900, l’année où les femmes entrent aux Jeux.', 2),
    ('f04dab97-01ca-5a61-9696-9fb59c088323'::uuid, '622fbe2a-98bf-52d5-bfc6-59cf04046940'::uuid, 'Combien de femmes participent aux Jeux de Paris en 1900 ?', 'mcq', '["2","220","2 200","22"]'::jsonb, 3, 'Elles sont 22, une première dans l’histoire olympique.', 3),
    ('415471de-88e1-5085-96e7-09aa72f91a04'::uuid, '622fbe2a-98bf-52d5-bfc6-59cf04046940'::uuid, 'Quelle nouveauté marque les Jeux de 1924 à Paris ?', 'mcq', '["Le premier village olympique","Le premier match de football","La première cérémonie sur un fleuve","La parité parfaite"]'::jsonb, 0, 'En 1924, les athlètes sont logés dans un village olympique, une première.', 4),
    ('d4066538-2baa-5dfb-bdc7-ce69c325eb53'::uuid, '622fbe2a-98bf-52d5-bfc6-59cf04046940'::uuid, 'Combien de médailles d’or le Finlandais Paavo Nurmi remporte-t-il à Paris en 1924 ?', 'mcq', '["1","10","3","5"]'::jsonb, 3, 'Paavo Nurmi gagne 5 ors en athlétisme, un exploit en une seule édition.', 5),
    ('c9b3e0f7-ec9c-59de-b6f7-919924abca37'::uuid, '622fbe2a-98bf-52d5-bfc6-59cf04046940'::uuid, 'Quel nageur de 1924 jouera ensuite Tarzan au cinéma ?', 'mcq', '["Eddy Merckx","Mark Spitz","Paavo Nurmi","Johnny Weissmuller"]'::jsonb, 3, 'Weissmuller gagne 3 ors à Paris avant de devenir l’acteur le plus célèbre à incarner Tarzan.', 6),
    ('a2f275ea-ab64-54a0-893a-cf7d54c4989f'::uuid, '622fbe2a-98bf-52d5-bfc6-59cf04046940'::uuid, 'Où se déroulent en 1924 les premiers Jeux d’hiver reconnus plus tard ?', 'mcq', '["À Grenoble","À Colombes","À Chamonix","À Lyon"]'::jsonb, 2, 'Chamonix a accueilli en 1924 les Jeux d’hiver, reconnus plus tard comme premiers Jeux d’hiver.', 7),
    ('0fac2118-c469-55b7-8072-64cf4fefaf14'::uuid, '622fbe2a-98bf-52d5-bfc6-59cf04046940'::uuid, 'Les Jeux de 2024 se sont déroulés du 26 juillet au 11 août.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Ils ont suivi par les Jeux paralympiques, du 28 août au 8 septembre.', 8),
    ('b6d1dcc6-651c-573a-a545-dcafb94e43fa'::uuid, '622fbe2a-98bf-52d5-bfc6-59cf04046940'::uuid, 'Qu’y a-t-il d’inédit dans la cérémonie d’ouverture des Jeux de 2024 ?', 'mcq', '["Elle a lieu dans un stade vide","Elle est organisée sous terre","Elle ne dure qu’une minute","Elle a lieu sur la Seine et non dans un stade"]'::jsonb, 3, 'La cérémonie se déroule sur la Seine : une première hors d’un stade.', 9),
    ('1f90f630-0a2d-5ae1-b0e9-fafe6ebe1b7a'::uuid, '622fbe2a-98bf-52d5-bfc6-59cf04046940'::uuid, 'Environ quelle part des sites de 2024 était existante ou temporaire ?', 'mcq', '["95 %","10 %","30 %","50 %"]'::jsonb, 0, 'Environ 95 % des sites existaient déjà ou étaient temporaires : peu de constructions neuves.', 10),
    ('f25671ee-298d-5538-927b-8990159328bc'::uuid, '622fbe2a-98bf-52d5-bfc6-59cf04046940'::uuid, 'Aux Jeux de 2024, la France a terminé 5e au tableau des médailles.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Elle se classe cinquième nation, une belle performance à domicile.', 11),
    ('f08b34b0-5319-5360-9923-ee870b9a0fce'::uuid, '622fbe2a-98bf-52d5-bfc6-59cf04046940'::uuid, 'Que sont devenus le village des athlètes de 2024 ?', 'mcq', '["Un parc d’attractions","Un musée de la Seine","Des logements à Saint-Denis et Saint-Ouen","Un stade de rugby"]'::jsonb, 2, 'Le village olympique est transformé en logements, un héritage concret pour les habitants.', 12),
    ('bf510e8e-3a9d-57cd-ba90-c23f19a6891f'::uuid, '73747a6e-9f82-5f7d-a523-e63c8f8ea96b'::uuid, 'Quelle est la première mission de l’arbitre ?', 'mcq', '["Aider l’équipe qui perd","Faire respecter la règle, la même pour tous","Donner de l’ambiance au match","Choisir les joueurs de chaque équipe"]'::jsonb, 1, 'L’arbitre applique la même règle aux deux camps pour que le jeu soit juste.', 1),
    ('9092220b-d525-59e9-b425-30a8c00e9b57'::uuid, '73747a6e-9f82-5f7d-a523-e63c8f8ea96b'::uuid, 'Dans quel sport l’arbitre explique-t-il ses décisions au micro, seul le capitaine pouvant lui parler ?', 'mcq', '["Le cyclisme","Le tennis","La natation","Le rugby"]'::jsonb, 3, 'Au rugby, l’arbitre s’explique et seul le capitaine échange avec lui : moins de contestation.', 2),
    ('ffe07f7e-ce52-5873-b9b4-3ba430b26f3a'::uuid, '73747a6e-9f82-5f7d-a523-e63c8f8ea96b'::uuid, 'Depuis quelle Coupe du monde le VAR est-il utilisé en football ?', 'mcq', '["1998","2006","2014","2018"]'::jsonb, 3, 'Le VAR débute à la Coupe du monde 2018 ; la goal-line technology date de 2014.', 3),
    ('5f4eb10e-ed1d-5172-853b-5ebc05f1d6be'::uuid, '73747a6e-9f82-5f7d-a523-e63c8f8ea96b'::uuid, 'Quel cas ne relève PAS de l’intervention du VAR ?', 'mcq', '["Un penalty","Un but","Une erreur d’identité","Un hors-jeu de touche"]'::jsonb, 3, 'Le VAR intervient pour un but, un penalty, un carton rouge direct ou une erreur d’identité, pas pour une touche.', 4),
    ('0a1d3c9e-c03f-5d9f-9535-1f8e038a9925'::uuid, '73747a6e-9f82-5f7d-a523-e63c8f8ea96b'::uuid, 'Que permet la goal-line technology, utilisée depuis la Coupe du monde 2014 ?', 'mcq', '["Savoir si le ballon a franchi la ligne de but","Mesurer la vitesse des joueurs","Désigner le meilleur joueur","Compter les passes"]'::jsonb, 0, 'Elle signale immédiatement à l’arbitre si le ballon a entièrement franchi la ligne.', 5),
    ('68cf0fe6-c5a5-58fa-9cb5-583481d87935'::uuid, '73747a6e-9f82-5f7d-a523-e63c8f8ea96b'::uuid, 'Le Hawk-Eye est utilisé au tennis depuis 2006.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Ce système suit la balle et indique si elle est dedans ou dehors.', 6),
    ('6c5cd595-90e7-54b2-94e5-5ba84382a3de'::uuid, '73747a6e-9f82-5f7d-a523-e63c8f8ea96b'::uuid, 'Qui conseille Jesse Owens au saut en longueur aux Jeux de Berlin en 1936 ?', 'mcq', '["Pierre de Coubertin","Lutz Long, son rival allemand","Paavo Nurmi","Johnny Weissmuller"]'::jsonb, 1, 'Lutz Long, un adversaire, aide Owens ; c’est un exemple célèbre de fair-play.', 7),
    ('4324ec84-19a2-58c6-b4e6-4a3494392d04'::uuid, '73747a6e-9f82-5f7d-a523-e63c8f8ea96b'::uuid, 'Que fait Paolo Di Canio en 2000 ?', 'mcq', '["Il refuse de marquer devant un gardien blessé","Il change de maillot en cours de match","Il marque un but de la main","Il quitte le terrain en protestant"]'::jsonb, 0, 'Il attrape le ballon à la main au lieu de profiter d’un gardien au sol.', 8),
    ('143ec1b9-b897-5458-97e7-a93b388b447f'::uuid, '73747a6e-9f82-5f7d-a523-e63c8f8ea96b'::uuid, 'Que fait Iván Fernández pour Abel Mutai en 2012 ?', 'mcq', '["Il le laisse gagner alors que Mutai s’était trompé de ligne d’arrivée","Il lui vole la victoire","Il abandonne la course","Il l’accuse de tricher"]'::jsonb, 0, 'Fernández ralentit et laisse passer Mutai : le geste est resté un symbole du fair-play.', 9),
    ('351bfa99-a04d-5cd0-b523-c70c24a44d08'::uuid, '73747a6e-9f82-5f7d-a523-e63c8f8ea96b'::uuid, 'Le VAR remplace l’arbitre sur le terrain.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'L’arbitre reste le patron : la vidéo l’aide dans quatre cas précis sans le remplacer.', 10),
    ('63644df6-d589-57b8-9d15-d2b1758c5fce'::uuid, '73747a6e-9f82-5f7d-a523-e63c8f8ea96b'::uuid, 'Le fair-play, c’est respecter l’adversaire et la règle même quand personne ne regarde.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Il s’agit de jouer juste par choix, même sans arbitre ni caméra.', 11),
    ('98bb7e23-e264-58cc-a75e-3b45e96bb046'::uuid, '73747a6e-9f82-5f7d-a523-e63c8f8ea96b'::uuid, 'Pourquoi l’arbitrage par les élèves est-il utile en EPS ?', 'mcq', '["Il permet aux élèves de choisir qui gagne","Il fait comprendre qu’un jeu n’existe que si tous acceptent la règle","Il supprime les règles","Il remplace le professeur"]'::jsonb, 1, 'En arbitrant, on voit le match d’un seul endroit et on mesure la difficulté de décider vite.', 12)
  ) AS v(id, quiz_id, question, kind, options, correct_index, explanation, position)
-- Le quiz doit exister : si le NOT EXISTS ci-dessus a écarté un quiz (une
-- leçon en avait déjà un), ses questions ne partent pas dans le vide.
 WHERE EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.id = v.quiz_id)
ON CONFLICT (id) DO NOTHING;

-- 5. Sonde finale ----------------------------------------------------------
DO $$
DECLARE
  n_vides integer;
  n_chap  integer;
BEGIN
  SELECT count(*) INTO n_chap FROM public.chapters c
   JOIN public.subjects s ON s.id = c.subject_id
   WHERE s.slug IN ('sport');
  SELECT count(*) INTO n_vides FROM public.subjects s
   WHERE s.slug IN ('sport')
     AND NOT EXISTS (SELECT 1 FROM public.chapters c WHERE c.subject_id = s.id);
  IF n_vides > 0 THEN
    RAISE EXCEPTION 'Migration 566 incomplète : % matiere(s) encore sans chapitre', n_vides;
  END IF;
  RAISE NOTICE 'Migration 566 OK : % chapitres sur les matieres visees.', n_chap;
END $$;
